function _lbEscape(str) {
  return String(str).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
}

function _renderAvatar(avatarValue) {
  if (avatarValue && avatarValue.startsWith("https://")) {
    return `<img src="${avatarValue}" alt="avatar" class="avatar-photo-img">`;
  }
  const icon = (avatarValue && /^[a-z_]+$/.test(avatarValue)) ? avatarValue : "person";
  return `<span class="material-symbols-outlined">${icon}</span>`;
}

function _currentProfileAvatarValue() {
  return localStorage.getItem("profilePicType") === "photo"
    ? (localStorage.getItem("profilePicRemoteURL") || "person")
    : (localStorage.getItem("profilePicValue") || "person");
}

function _lbAvatarHtml(entry) {
  return `<span class="lb-avatar">${_renderAvatar(entry.avatar)}</span>`;
}

function _rankBadgeHtml(rank) {
  const labels = ["1st", "2nd", "3rd"];
  const cls = ["lb-rank-gold", "lb-rank-silver", "lb-rank-bronze"];
  if (rank <= 3) return `<span class="lb-rank-badge ${cls[rank-1]}">${labels[rank-1]}</span>`;
  return `<span class="lb-rank-num">#${rank}</span>`;
}

// Mercies
const MERCY_PROMPTS = [
  "What is one good gift you can praise God for today?",
  "What is one ordinary blessing you noticed today?",
  "What truth from Scripture helped you think clearly today?",
  "What is one wise choice you made or want to make today?",
  "What is something God provided that you want to remember?",
  "What is one way you saw someone show kindness today?",
  "What is one lesson from today you want to carry into tomorrow?",
  "What is one reason to praise the Lord today?",
  "What is something you are praying about with trust and wisdom?",
  "What verse, truth, or biblical reminder shaped your day?",
  "Where did you need patience, humility, or wisdom today?",
  "What is one thing you can thank God for even if today was hard?",
  "What responsibility did you try to handle faithfully today?",
  "What is one moment from today worth remembering?",
  "What is something you ate today that you enjoyed?",
  "What conversation from today are you thankful for?",
  "What simple comfort did you receive today?",
  "What part of creation caught your attention today?",
  "What task did you get through that you can thank God for?",
  "What song, verse, or thought helped your heart today?",
  "What small moment made your day lighter?",
  "What is one thing about your home, work, or routine you can praise God for?",
  "What is one answered prayer, large or small, you want to remember?"
];

const MERCY_FRIEND_PROMPTS = [
  "What is one way [friend] has encouraged you?",
  "What is something you appreciate about [friend]?",
  "What is one Christlike quality you see in [friend]?",
  "What is a time [friend] made you smile?",
  "What is one way God has used [friend] to bless your life?",
  "What is one strength you see in [friend]?",
  "What is one memory with [friend] you are thankful for?",
  "What is a verse or truth that reminds you of [friend]?",
  "How has [friend] been faithful, kind, or steady?",
  "What prayer would you write for [friend] this week?"
];

function _mercyPromptToday() {
  return MERCY_PROMPTS[Math.floor(Date.now() / 86400000) % MERCY_PROMPTS.length];
}

function _mercyCleanFriendName(friendName = "") {
  const name = String(friendName || "").trim();
  if (!name || /^tag (one|another) friend/i.test(name)) return "your friend";
  return name;
}

function _mercyFriendPrompt(friendName = "your friend") {
  const prompt = MERCY_FRIEND_PROMPTS[Math.floor(Math.random() * MERCY_FRIEND_PROMPTS.length)];
  return prompt.replaceAll("[friend]", _mercyCleanFriendName(friendName));
}

function _mercyFriendPromptText(promptText, friendName = "your friend") {
  const cleanName = _mercyCleanFriendName(friendName);
  const text = String(promptText || "").trim();
  if (!text || /^Encourage .+ with a praise this week\.$/i.test(text)) return _mercyFriendPrompt(cleanName);
  return text.replaceAll("[friend]", cleanName).replace(/Tag one friend \(optional\)/gi, cleanName);
}

function showMerciesView(view) {
  document.querySelectorAll('[data-mercy-view]').forEach(btn => btn.classList.toggle('active', btn.dataset.mercyView === view));
  document.getElementById('merciesFeedView')?.classList.toggle('active', view === 'feed');
  document.getElementById('merciesJournalView')?.classList.toggle('active', view === 'journal');
  document.querySelector('#merciesPage .mercies-section-head')?.classList.toggle('hidden', view === 'journal');
  if (view === 'journal') startMerciesJournal();
}

function setMerciesFilter(filter) {
  _merciesFilter = filter || 'latest';
  renderMerciesFeed();
}

function startMerciesFeed() {
  const list = document.getElementById('merciesFeedList');
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!list) return;
  showMerciesView('feed');
  refreshPendingMercyFriendEncouragement();
  clearTimeout(_merciesFeedRetryTimer);
  if (!uid) {
    if (!_authReady) {
      // Auth is still resolving — show neutral state and retry quickly
      list.innerHTML = '<p class="study-board-empty">Loading Praises...</p>';
      _merciesFeedRetryTimer = setTimeout(startMerciesFeed, 500);
    } else {
      list.innerHTML = '<div class="mercies-empty"><span class="material-symbols-outlined">account_circle</span><strong>Sign in to see Praises</strong><p>Your feed will load as soon as your account is ready.</p></div>';
    }
    return;
  }
  if (!window.Mercies?.listen) {
    list.innerHTML = '<p class="study-board-empty">Loading Praises...</p>';
    _merciesFeedRetryTimer = setTimeout(startMerciesFeed, 500);
    return;
  }
  if (_merciesUnsub) { renderMerciesFeed(); return; }
  list.innerHTML = '<p class="study-board-empty">Loading Praises...</p>';
  _merciesFeedRetryTimer = setTimeout(() => {
    if (list.textContent?.includes('Loading Praises')) {
      list.innerHTML = '<div class="mercies-empty"><span class="material-symbols-outlined">hourglass_empty</span><strong>Still loading</strong><p>Checking your feed connection...</p></div>';
      if (_merciesUnsub) { _merciesUnsub(); _merciesUnsub = null; }
      setTimeout(startMerciesFeed, 1200);
    }
  }, 5000);
  _merciesUnsub = window.Mercies.listen(uid, friendsList, posts => {
    clearTimeout(_merciesFeedRetryTimer);
    _merciesPosts = posts || [];
    renderMerciesFeed();
  });
}

function renderMerciesFeed() {
  const list = document.getElementById('merciesFeedList');
  if (!list) return;
  const uid = window.Auth?.getCurrentUser()?.uid;
  const filtered = _merciesPosts.filter(post => {
    if (_merciesFilter === 'scripture') return !!post.scripture?.text;
    return true;
  });
  if (_merciesFilter === 'oldest') {
    filtered.sort((a, b) => (a.createdAtMs || 0) - (b.createdAtMs || 0));
  }
  const posts = filtered.slice(0, _merciesVisibleCount);
  document.getElementById('merciesLoadMore')?.classList.toggle('hidden', filtered.length <= _merciesVisibleCount);
  if (!posts.length) {
    list.innerHTML = `<div class="mercies-empty"><span class="material-symbols-outlined">photo_camera</span><strong>No Praises yet</strong><p>Post a photo and remember one ordinary blessing from today.</p><button onclick="openMercyComposer()">Post a Praise</button></div>`;
    return;
  }
  list.innerHTML = posts.map(_mercyCardHtml).join('');
}

function loadMoreMercies() {
  _merciesVisibleCount += 10;
  renderMerciesFeed();
}

function savePendingMercyFriendEncouragement(friendUid, friendName = 'your friend') {
  if (!friendUid) return;
  const pending = {
    friendUid,
    friendName,
    promptText: _mercyFriendPromptText('', friendName),
    createdAtMs: Date.now(),
    expiresAtMs: Date.now() + 24 * 60 * 60 * 1000
  };
  _pendingMercyFriendEncouragement = pending;
  localStorage.setItem('pendingMercyFriendEncouragement', JSON.stringify(pending));
  refreshPendingMercyFriendEncouragement();
}

function syncPendingMercyFriendEncouragement(pending) {
  if (!pending || !pending.friendUid) {
    const local = refreshPendingMercyFriendEncouragement();
    if (!local) document.getElementById('mercyPendingFriendAction')?.classList.add('hidden');
    return;
  }
  const normalized = {
    friendUid: pending.friendUid,
    friendName: pending.friendName || 'your friend',
    promptText: _mercyFriendPromptText(pending.promptText, pending.friendName || 'your friend'),
    createdAtMs: Number(pending.createdAtMs || Date.now()),
    expiresAtMs: Number(pending.expiresAtMs || Date.now() + 24 * 60 * 60 * 1000)
  };
  _pendingMercyFriendEncouragement = normalized;
  localStorage.setItem('pendingMercyFriendEncouragement', JSON.stringify(normalized));
  refreshPendingMercyFriendEncouragement();
}

function _mercyCountdownText(expiresAtMs) {
  const remaining = Math.max(0, Number(expiresAtMs || 0) - Date.now());
  const hours = Math.floor(remaining / 3600000);
  const minutes = Math.ceil((remaining % 3600000) / 60000);
  if (hours >= 1) return `${hours}h ${String(minutes).padStart(2, '0')}m left`;
  return `${Math.max(1, minutes)}m left`;
}

function refreshPendingMercyFriendEncouragement() {
  let pending = _pendingMercyFriendEncouragement;
  if (!pending) {
    try { pending = JSON.parse(localStorage.getItem('pendingMercyFriendEncouragement') || 'null'); }
    catch { pending = null; }
  }
  if (!pending || !pending.friendUid || (pending.expiresAtMs || 0) <= Date.now()) {
    _pendingMercyFriendEncouragement = null;
    localStorage.removeItem('pendingMercyFriendEncouragement');
    document.getElementById('mercyPendingFriendAction')?.classList.add('hidden');
    return null;
  }
  _pendingMercyFriendEncouragement = pending;
  const btn = document.getElementById('mercyPendingFriendAction');
  if (btn) {
    btn.classList.remove('hidden');
    const name = pending.friendName || 'your friend';
    const title = document.getElementById('mercyPendingFriendTitle');
    const sub = document.getElementById('mercyPendingFriendSub');
    if (title) title.textContent = `Encourage ${name}`;
    if (sub) sub.textContent = `Locked to ${name}. Expires in ${_mercyCountdownText(pending.expiresAtMs)}.`;
  }
  return pending;
}

setInterval(() => {
  if (_pendingMercyFriendEncouragement) refreshPendingMercyFriendEncouragement();
}, 60000);

function openPendingMercyFriendEncouragement() {
  const pending = refreshPendingMercyFriendEncouragement();
  if (!pending) return;
  openMercyComposer({
    friendUid: pending.friendUid,
    friendName: pending.friendName || 'your friend',
    lockedFriend: true,
    promptText: _mercyFriendPromptText(pending.promptText, pending.friendName || 'your friend')
  });
}

function clearPendingMercyFriendEncouragement(friendUid) {
  const pending = refreshPendingMercyFriendEncouragement();
  if (!pending || (friendUid && pending.friendUid !== friendUid)) return;
  _pendingMercyFriendEncouragement = null;
  localStorage.removeItem('pendingMercyFriendEncouragement');
  document.getElementById('mercyPendingFriendAction')?.classList.add('hidden');
  window.Mercies?.clearPendingFriendEncouragement?.(window.Auth?.getCurrentUser()?.uid).catch(() => {});
}

function _mercyCardHtml(post) {
  const reactions = post.reactions || {};
  const uid = window.Auth?.getCurrentUser()?.uid;
  const mine = uid && post.authorUid === uid;
  const scripture = post.scripture?.text ? _mercyScriptureCard(post.scripture, post.scriptureCard) : '';
  const hasPhoto = !!post.imageUrl;
  const hasMedia = hasPhoto || scripture;
  const slideDots = scripture && hasPhoto ? '<div class="mercy-slide-dots"><span></span><span></span></div>' : '';
  const saved = !!uid && (post.journalSavedBy || []).includes(uid);
  const taggedNames = post.taggedFriendNames?.length ? post.taggedFriendNames : (post.taggedFriendName ? [post.taggedFriendName] : []);
  const mediaStyle = post.imageAspectRatio
    ? ` style="--mercy-photo-aspect:${Number(post.imageAspectRatio).toFixed(4)}"`
    : '';
  const reactionEntries = Object.entries(reactions).map(([reactUid, value]) => ({
    uid: reactUid,
    label: typeof value === 'string' ? value : value?.label,
    name: typeof value === 'string' ? 'Friend' : value?.name || 'Friend',
    avatar: typeof value === 'string' ? 'person' : value?.avatar || 'person'
  })).filter(r => r.label);
  return `<article class="mercy-card">
    <div class="mercy-card-top">
      <span class="mercy-avatar">${_renderAvatar(post.authorAvatar || 'person')}</span>
      <div><strong>${_lbEscape(post.authorName || 'Someone')}</strong><small>${_communityPostTime(post)}</small></div>
      <span class="mercy-category">${_lbEscape(post.promptCategory || 'Praise')}</span>
      ${post.scripture?.ref ? `<span class="mercy-category mercy-scripture-chip"><span class="material-symbols-outlined">menu_book</span>${_lbEscape(post.scripture.ref)}</span>` : ''}
    </div>
    ${hasMedia ? `<div class="mercy-media${scripture ? ' has-scripture' : ''}"${mediaStyle}>
      ${hasPhoto ? `<div class="mercy-slide"><img loading="lazy" src="${_lbEscape(post.imageUrl)}" alt="Praise photo" onload="syncMercyImageAspect(this)"></div>` : ''}
      ${scripture}
    </div>` : ''}
    ${slideDots}
    ${post.promptText ? `<div class="mercy-prompt">${_lbEscape(post.promptText || '')}</div>` : ''}
    <p class="mercy-body">${_lbEscape(post.body || '')}</p>
    <div class="mercy-chips">
      ${taggedNames.map(name => `<span><span class="material-symbols-outlined">person_heart</span>${_lbEscape(name)}</span>`).join('')}
    </div>
    ${mine ? `<div class="mercy-owner-actions">
      <button class="mercy-journal-action ${saved ? 'saved' : ''}" onclick="saveMercyToJournal('${post.id}', null, this)"><span class="material-symbols-outlined">${saved ? 'bookmark_added' : 'bookmark'}</span>${saved ? 'Saved' : 'Journal'}</button>
      <button class="mercy-delete-action" onclick="deleteMercyPost('${post.id}')"><span class="material-symbols-outlined">delete</span>Delete</button>
    </div>` : `<div class="mercy-reactions">
      ${['Amen','Thankful','Praying','Encouraged'].map(label => {
        const active = reactions[uid]?.label === label || reactions[uid] === label;
        const count = Object.values(reactions).filter(r => (typeof r === 'string' ? r : r?.label) === label).length;
        return `<button class="${active ? 'active' : ''}" onclick="reactMercyPost('${post.id}','${label}')">${label}${count ? `<small>${count}</small>` : ''}</button>`;
      }).join('')}
    </div>`}
    <div class="mercy-social-row">
      <button class="cp-comment-btn" onclick="openMercyComments('${post.id}')"><span class="material-symbols-outlined">chat_bubble</span><small>${Number(post.commentCount || 0)}</small></button>
      ${_mercyReactionStackHtml(post.id, reactionEntries)}
    </div>
  </article>`;
}

function _mercyReactionStackHtml(postId, entries = []) {
  if (!entries.length) return '';
  const shown = entries.slice(0, 4);
  const extra = entries.length - shown.length;
  return `<button class="cp-reaction-stack mercy-reaction-stack" onclick="openMercyReactions('${postId}')">
    ${shown.map(r => `<span>${_renderAvatar(r.avatar || 'person')}</span>`).join('')}
    ${extra > 0 ? `<em>+${extra}</em>` : ''}
  </button>`;
}

function _mercyScriptureCard(scripture, options = {}) {
  const bg = options.bg || 'theme';
  const font = options.font || 'system';
  const color = options.color || 'var(--font-color)';
  return `<div class="mercy-slide mercy-scripture-card mercy-scripture-${bg} mercy-font-${font}" style="--mercy-scripture-color:${_lbEscape(color)}">
    <span>${_lbEscape(scripture.ref || 'Scripture')}</span>
    <p>${_lbEscape(scripture.text || '')}</p>
  </div>`;
}

function openMercyComposer(prefill = {}) {
  if (!window.Auth?.getCurrentUser()) { alert('Sign in to post a Praise.'); return; }
  _mercyImageBlob = null;
  _mercyImageDataUrl = null;
  _mercyPostWithoutPhoto = false;
  _mercyPhotoAspectRatio = 4 / 3;
  _mercyPromptChoiceMode = 'guided';
  _mercyLockedFriendUid = prefill.lockedFriend ? (prefill.friendUid || null) : null;
  _mercyPromptMode = prefill.friendUid ? 'friend' : 'regular';
  clearMercyPhoto();
  _populateMercyFriendSelect(prefill.friendUid || '', prefill.friendName || '', prefill.promptText || '');
  if (prefill.friendUid && prefill.friendName) {
    const sel = document.getElementById('mercyFriendSelect');
    if (sel && ![...sel.options].some(opt => opt.value === prefill.friendUid)) {
      const opt = document.createElement('option');
      opt.value = prefill.friendUid;
      opt.textContent = prefill.friendName;
      opt.dataset.name = prefill.friendName;
      opt.selected = true;
      sel.appendChild(opt);
    }
    if (sel) sel.value = prefill.friendUid;
  }
  _populateMercyPromptSelect(prefill.promptText);
  populateMercyBooks();
  const friendMode = document.getElementById('mercyFriendEncouragement');
  if (friendMode) friendMode.checked = !!prefill.friendUid;
  const noPhoto = document.getElementById('mercyNoPhoto');
  if (noPhoto) noPhoto.checked = false;
  const extraFriends = document.getElementById('mercyExtraFriends');
  if (extraFriends) extraFriends.innerHTML = '';
  const scriptureToggle = document.getElementById('mercyAttachScripture');
  if (scriptureToggle) scriptureToggle.checked = false;
  document.getElementById('mercyBody').value = '';
  document.getElementById('mercyScriptureRef').value = '';
  document.getElementById('mercyScriptureText').value = '';
  document.getElementById('mercyCustomPrompt').value = '';
  setMercyPromptMode('guided');
  updateMercyLockedFriendUI();
  toggleMercyScripture();
  document.getElementById('mercySaveThis').checked = localStorage.getItem('merciesAutoSave') === 'true';
  toggleMercyNoPhoto();
  document.getElementById('mercyComposerModal')?.classList.add('open');
  requestAnimationFrame(() => {
    const card = document.querySelector('#mercyComposerModal .mercy-composer-card');
    if (card) card.scrollTop = 0;
  });
}

function closeMercyComposer() {
  document.getElementById('mercyComposerModal')?.classList.remove('open');
  _mercyLockedFriendUid = null;
}

function updateMercyLockedFriendUI() {
  const locked = !!_mercyLockedFriendUid;
  const notice = document.getElementById('mercyLockedFriendNotice');
  const picker = document.getElementById('mercyFriendPickerBtn');
  const addBtn = document.getElementById('mercyAddFriendBtn');
  const friendToggle = document.getElementById('mercyFriendEncouragement');
  notice?.classList.toggle('hidden', !locked);
  if (picker) {
    picker.disabled = locked;
    picker.classList.toggle('locked', locked);
  }
  if (addBtn) addBtn.disabled = locked || !!friendToggle?.checked;
  if (friendToggle) {
    friendToggle.checked = locked || friendToggle.checked;
    friendToggle.disabled = locked;
  }
}

function setMercyPromptMode(mode = 'guided') {
  _mercyPromptChoiceMode = ['guided', 'custom', 'none'].includes(mode) ? mode : 'guided';
  document.querySelectorAll('#mercyPromptMode button').forEach(btn => btn.classList.toggle('active', btn.dataset.promptMode === _mercyPromptChoiceMode));
  document.getElementById('mercyPromptSelect')?.classList.toggle('hidden', _mercyPromptChoiceMode !== 'guided');
  document.getElementById('mercyCustomPrompt')?.classList.toggle('hidden', _mercyPromptChoiceMode !== 'custom');
  document.getElementById('mercyFriendEncouragement')?.closest('.mercy-toggle-card')?.classList.toggle('hidden', _mercyPromptChoiceMode !== 'guided');
}

function _currentMercyPromptText() {
  if (_mercyPromptChoiceMode === 'none') return '';
  if (_mercyPromptChoiceMode === 'custom') return document.getElementById('mercyCustomPrompt')?.value.trim() || '';
  return document.getElementById('mercyPromptSelect')?.value || _mercyPromptToday();
}

function _populateMercyPromptSelect(selectedText) {
  const sel = document.getElementById('mercyPromptSelect');
  if (!sel) return;
  const prompts = _mercyPromptMode === 'friend'
    ? MERCY_FRIEND_PROMPTS.map(p => p.replaceAll('[friend]', _mercyCleanFriendName(_selectedMercyFriendName())))
    : MERCY_PROMPTS;
  const defaultPrompt = selectedText || (_mercyPromptMode === 'friend' ? prompts[0] : _mercyPromptToday());
  sel.innerHTML = prompts.map(p => `<option value="${_lbEscape(p)}"${p === defaultPrompt ? ' selected' : ''}>${_lbEscape(p)}</option>`).join('');
}

function _populateMercyFriendSelect(selectedUid = '', selectedName = '', selectedPromptText = '') {
  const sel = document.getElementById('mercyFriendSelect');
  _fillMercyFriendSelect(sel, selectedUid, 'Tag one friend (optional)');
  if (sel && selectedUid && selectedName && ![...sel.options].some(opt => opt.value === selectedUid)) {
    const opt = document.createElement('option');
    opt.value = selectedUid;
    opt.textContent = selectedName;
    opt.dataset.name = selectedName;
    opt.selected = true;
    sel.appendChild(opt);
  }
  setTimeout(() => _populateMercyPromptSelect(selectedPromptText), 150);
}

function addMercyFriendTag(selectedUid = '') {
  const wrap = document.getElementById('mercyExtraFriends');
  if (!wrap || document.getElementById('mercyFriendEncouragement')?.checked) return;
  const row = document.createElement('div');
  row.className = 'mercy-extra-friend-row';
  const selectId = `mercyExtraFriend_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
  row.innerHTML = `<select id="${selectId}" class="mercy-extra-friend-select" onchange="updateMercyFriendOptions()" hidden><option value="">Tag another friend</option></select><button class="mercy-picker-button" type="button" onclick="openMercyFriendPicker('${selectId}')"><span>Tag another friend</span><span class="material-symbols-outlined">expand_more</span></button><button type="button" aria-label="Remove friend tag" onclick="this.closest('.mercy-extra-friend-row')?.remove(); updateMercyFriendOptions();"><span class="material-symbols-outlined">close</span></button>`;
  wrap.appendChild(row);
  const sel = row.querySelector('select');
  _fillMercyFriendSelect(sel, selectedUid, 'Tag another friend');
}

function _selectedMercyFriendUids() {
  return [
    document.getElementById('mercyFriendSelect')?.value || '',
    ...[...document.querySelectorAll('.mercy-extra-friend-select')].map(sel => sel.value || '')
  ].filter(Boolean);
}

function _fillMercyFriendSelect(sel, selectedUid = '', placeholder = 'Tag one friend (optional)') {
  if (!sel) return;
  sel.innerHTML = `<option value="">${placeholder}</option>`;
  const selected = new Set(_selectedMercyFriendUids().filter(uid => uid !== selectedUid));
  Promise.all((friendsList || []).map(uid => window.Friends?.getUser(uid).catch(() => null)))
    .then(users => users.filter(Boolean).sort((a, b) => (a.displayName || a.username || '').localeCompare(b.displayName || b.username || '')))
    .then(users => {
      users.forEach(u => {
        const name = u?.displayName || u?.username || 'Friend';
        const opt = document.createElement('option');
        opt.value = u.uid; opt.textContent = name; opt.dataset.name = name;
        opt.disabled = selected.has(u.uid);
        if (u.uid === selectedUid) opt.selected = true;
        sel.appendChild(opt);
      });
      updateMercyFriendPickerButtons();
    }).catch(() => {});
}

function updateMercyFriendOptions() {
  _fillMercyFriendSelect(document.getElementById('mercyFriendSelect'), document.getElementById('mercyFriendSelect')?.value || '', 'Tag one friend (optional)');
  document.querySelectorAll('.mercy-extra-friend-select').forEach(sel => _fillMercyFriendSelect(sel, sel.value || '', 'Tag another friend'));
}

function updateMercyFriendPickerButtons() {
  const mainSel = document.getElementById('mercyFriendSelect');
  const mainBtn = document.getElementById('mercyFriendPickerBtn');
  if (mainSel && mainBtn) {
    const label = mainBtn.querySelector('span');
    if (label) label.textContent = mainSel.value ? (mainSel.selectedOptions?.[0]?.textContent || 'Friend') : 'Tag one friend (optional)';
  }
  document.querySelectorAll('.mercy-extra-friend-row').forEach(row => {
    const sel = row.querySelector('select');
    const btn = row.querySelector('.mercy-picker-button');
    if (sel && btn) {
      const label = btn.querySelector('span');
      if (label) label.textContent = sel.value ? (sel.selectedOptions?.[0]?.textContent || 'Friend') : 'Tag another friend';
    }
  });
}

async function openMercyFriendPicker(selectId) {
  if (_mercyLockedFriendUid && selectId === 'mercyFriendSelect') return;
  _mercyFriendPickerTargetId = selectId;
  const list = document.getElementById('mercyFriendPickerList');
  if (!list) return;
  const selected = new Set(_selectedMercyFriendUids());
  const target = document.getElementById(selectId);
  if (target?.value) selected.delete(target.value);
  list.innerHTML = '<p class="fr-loading">Loading friends...</p>';
  document.getElementById('mercyFriendPickerOverlay')?.classList.remove('hidden');
  const users = (await Promise.all((friendsList || []).map(uid => window.Friends?.getUser(uid).catch(() => null))))
    .filter(Boolean)
    .sort((a, b) => (a.displayName || a.username || '').localeCompare(b.displayName || b.username || ''));
  list.innerHTML = users.length ? users.map(u => {
    const name = _lbEscape(u.displayName || u.username || 'Friend');
    const disabled = selected.has(u.uid);
    const active = target?.value === u.uid;
    return `<button class="mercy-friend-choice${active ? ' selected' : ''}" ${disabled ? 'disabled' : ''} onclick="selectMercyFriend('${selectId}','${u.uid}','${name.replace(/'/g, "\\'")}')">
      <span class="mercy-avatar">${_renderAvatar(_frAvatarValue(u))}</span><span>${name}</span>${active ? '<span class="material-symbols-outlined">check</span>' : ''}
    </button>`;
  }).join('') : '<p class="fr-empty-sm">Add friends to tag them.</p>';
}

function closeMercyFriendPicker() {
  document.getElementById('mercyFriendPickerOverlay')?.classList.add('hidden');
  _mercyFriendPickerTargetId = null;
}

function selectMercyFriend(selectId, uid, name) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  let opt = [...sel.options].find(o => o.value === uid);
  if (!opt) {
    opt = document.createElement('option');
    opt.value = uid; opt.textContent = name; opt.dataset.name = name;
    sel.appendChild(opt);
  }
  sel.value = uid;
  closeMercyFriendPicker();
  onMercyFriendChanged();
}

function _selectedMercyFriendName() {
  const sel = document.getElementById('mercyFriendSelect');
  if (!sel?.value) return '';
  const opt = sel.selectedOptions?.[0];
  return opt?.dataset?.name || opt?.textContent || '';
}

function toggleMercyFriendMode() {
  _mercyPromptMode = document.getElementById('mercyFriendEncouragement')?.checked ? 'friend' : 'regular';
  const friendMode = _mercyPromptMode === 'friend';
  const addBtn = document.getElementById('mercyAddFriendBtn');
  if (addBtn) addBtn.disabled = friendMode || !!_mercyLockedFriendUid;
  if (friendMode || _mercyLockedFriendUid) document.getElementById('mercyExtraFriends')?.replaceChildren();
  _populateMercyPromptSelect();
  updateMercyLockedFriendUI();
}

function onMercyFriendChanged() {
  _populateMercyPromptSelect();
  updateMercyFriendOptions();
}

function onMercyPromptChanged() {}

async function populateMercyBooks() {
  await loadRhemaScripts().catch(() => {});
  const sel = document.getElementById('mercyScriptureBook');
  if (!sel) return;
  const books = window.RhemaEnglishBooks || [];
  sel.innerHTML = books.map(book => `<option value="${book.code}">${_lbEscape(book.name)}</option>`).join('');
  if (books.find(book => book.code === 'PSA')) sel.value = 'PSA';
  updateMercyRefPills();
  populateMercyChapters();
}

function populateMercyChapters() {
  const book = document.getElementById('mercyScriptureBook')?.value;
  const sel = document.getElementById('mercyScriptureChapter');
  const data = window.RhemaMSB?.[book] || {};
  if (!sel) return;
  const chapters = Object.keys(data).map(Number).sort((a, b) => a - b);
  sel.innerHTML = chapters.map(ch => `<option value="${ch}">${ch}</option>`).join('');
  updateMercyRefPills();
  populateMercyVerses();
}

function populateMercyVerses() {
  const book = document.getElementById('mercyScriptureBook')?.value;
  const chapter = document.getElementById('mercyScriptureChapter')?.value;
  const sel = document.getElementById('mercyScriptureVerse');
  const data = window.RhemaMSB?.[book]?.[chapter] || {};
  if (!sel) return;
  const verses = Object.keys(data).map(Number).sort((a, b) => a - b);
  sel.innerHTML = verses.map(v => `<option value="${v}">${v}</option>`).join('');
  updateMercyRefPills();
  updateMercyScriptureFromPicker();
}

function updateMercyScriptureFromPicker() {
  const book = document.getElementById('mercyScriptureBook')?.value;
  const chapter = document.getElementById('mercyScriptureChapter')?.value;
  const verse = document.getElementById('mercyScriptureVerse')?.value;
  const bookName = (window.RhemaEnglishBooks || []).find(b => b.code === book)?.name || book;
  const text = _rhemaEnglishText(book, chapter, verse, 'MSB');
  const ref = document.getElementById('mercyScriptureRef');
  const textEl = document.getElementById('mercyScriptureText');
  if (ref) ref.value = book && chapter && verse ? `${bookName} ${chapter}:${verse}` : '';
  if (textEl) textEl.value = text || '';
  updateMercyRefPills();
  updateMercyScripturePreview();
}

function updateMercyRefPills() {
  const book = document.getElementById('mercyScriptureBook')?.value;
  const chapter = document.getElementById('mercyScriptureChapter')?.value;
  const verse = document.getElementById('mercyScriptureVerse')?.value;
  const bookName = (window.RhemaEnglishBooks || []).find(b => b.code === book)?.name || 'Book';
  const b = document.getElementById('mercyBookPill');
  const c = document.getElementById('mercyChapterPill');
  const v = document.getElementById('mercyVersePill');
  const pillHtml = (icon, text) => `<span class="material-symbols-outlined">${icon}</span><strong>${_lbEscape(text)}</strong><span class="material-symbols-outlined">expand_more</span>`;
  if (b) b.innerHTML = pillHtml('menu_book', bookName);
  if (c) c.innerHTML = pillHtml('format_list_numbered', chapter ? `Chapter ${chapter}` : 'Chapter');
  if (v) v.innerHTML = pillHtml('pin', verse ? `Verse ${verse}` : 'Verse');
}

