function toggleMercyScripture() {
  const enabled = !!document.getElementById('mercyAttachScripture')?.checked;
  const controls = document.getElementById('mercyScriptureControls');
  controls?.classList.toggle('disabled', !enabled);
  controls?.querySelectorAll('select,input,textarea').forEach(el => {
    el.disabled = !enabled;
  });
  if (enabled && !document.getElementById('mercyScriptureBook')?.options?.length) populateMercyBooks();
  updateMercyScripturePreview();
}

function updateMercyScripturePreview() {
  const preview = document.getElementById('mercyScripturePreview');
  if (!preview) return;
  const enabled = !!document.getElementById('mercyAttachScripture')?.checked;
  const ref = document.getElementById('mercyScriptureRef')?.value || 'Scripture';
  const text = document.getElementById('mercyScriptureText')?.value || 'Select a verse to preview the card.';
  const bg = document.getElementById('mercyScriptureBg')?.value || 'theme';
  const font = document.getElementById('mercyScriptureFont')?.value || 'system';
  const color = document.getElementById('mercyScriptureColor')?.value || '#123532';
  preview.className = `mercy-scripture-preview mercy-scripture-${bg} mercy-font-${font}${enabled ? '' : ' disabled'}`;
  preview.style.setProperty('--mercy-scripture-color', color);
  preview.innerHTML = `<span>${_lbEscape(ref)}</span><p>${_lbEscape(text)}</p>`;
}

async function handleMercyPhotoSelected(input) {
  const file = input.files?.[0];
  input.value = '';
  if (!file) return;
  try {
    _mercyOriginalImageFile = file;
    _mercyPostWithoutPhoto = false;
    const noPhoto = document.getElementById('mercyNoPhoto');
    if (noPhoto) noPhoto.checked = false;
    if (_mercyPhotoPreviewUrl) URL.revokeObjectURL(_mercyPhotoPreviewUrl);
    _mercyPhotoPreviewUrl = URL.createObjectURL(file);
    const dims = await getMercyImageDimensions(file).catch(() => null);
    _mercyPhotoAspectRatio = dims?.aspectRatio || 4 / 3;
    document.getElementById('mercyPhotoPreview').src = _mercyPhotoPreviewUrl;
    updateMercyPhotoPreviewAspect();
    document.getElementById('mercyPhotoPreviewWrap')?.classList.remove('hidden');
    document.getElementById('mercyPhotoPicker')?.classList.add('hidden');
    const result = await compressMercyImage(file);
    _mercyImageBlob = result.blob;
    _mercyImageDataUrl = result.dataUrl;
    _mercyPhotoAspectRatio = result.aspectRatio || _mercyPhotoAspectRatio;
    updateMercyPhotoPreviewAspect();
  } catch (e) {
    alert('Could not prepare that photo. Try a different image.');
  }
}

function clearMercyPhoto() {
  _mercyImageBlob = null;
  _mercyImageDataUrl = null;
  _mercyOriginalImageFile = null;
  _mercyPhotoAspectRatio = 4 / 3;
  if (_mercyPhotoPreviewUrl) URL.revokeObjectURL(_mercyPhotoPreviewUrl);
  _mercyPhotoPreviewUrl = null;
  document.getElementById('mercyPhotoPreviewWrap')?.classList.add('hidden');
  document.getElementById('mercyPhotoPicker')?.classList.remove('hidden');
}

function toggleMercyNoPhoto() {
  _mercyPostWithoutPhoto = !!document.getElementById('mercyNoPhoto')?.checked;
  document.getElementById('mercyPhotoPicker')?.classList.toggle('hidden', _mercyPostWithoutPhoto || !!_mercyOriginalImageFile);
  if (_mercyPostWithoutPhoto) clearMercyPhoto();
  document.getElementById('mercyPhotoPicker')?.classList.toggle('hidden', _mercyPostWithoutPhoto);
}

function updateMercyPhotoPreviewAspect() {
  const wrap = document.getElementById('mercyPhotoPreviewWrap');
  if (wrap) wrap.style.setProperty('--mercy-photo-aspect', String(_mercyPhotoAspectRatio || (4 / 3)));
}

function syncMercyImageAspect(img) {
  const media = img?.closest?.('.mercy-media');
  if (!media || !img.naturalWidth || !img.naturalHeight) return;
  media.style.setProperty('--mercy-photo-aspect', String(img.naturalWidth / img.naturalHeight));
}

async function getMercyImageDimensions(file) {
  let url = null;
  try {
    const img = await new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = reject;
      url = URL.createObjectURL(file);
      image.src = url;
    });
    return { width: img.width, height: img.height, aspectRatio: img.width / Math.max(1, img.height) };
  } finally {
    if (url) URL.revokeObjectURL(url);
  }
}

async function compressMercyImage(file, options = {}) {
  let url = null;
  const img = await new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = reject;
    url = URL.createObjectURL(file);
    image.src = url;
  });
  if (url) URL.revokeObjectURL(url);
  const max = 1600;
  let scale = Math.min(1, max / Math.max(img.width, img.height));
  const canvas = document.createElement('canvas');
  const type = canvas.toDataURL('image/webp').startsWith('data:image/webp') ? 'image/webp' : 'image/jpeg';
  let quality = 0.76;
  let blob = null;
  let dataUrl = '';
  for (let attempt = 0; attempt < 6; attempt++) {
    canvas.width = Math.max(1, Math.round(img.width * scale));
    canvas.height = Math.max(1, Math.round(img.height * scale));
    canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
    blob = await new Promise(resolve => canvas.toBlob(resolve, type, quality));
    if (blob && blob.size <= 360 * 1024) break;
    quality = Math.max(0.52, quality - 0.06);
    scale *= 0.86;
  }
  if (!blob) throw new Error('Praise image compression failed');
  dataUrl = canvas.toDataURL(type, quality);
  return { blob, dataUrl, type, aspectRatio: canvas.width / Math.max(1, canvas.height) };
}

async function submitMercyPost() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const body = document.getElementById('mercyBody')?.value.trim() || '';
  if (!body) { alert('Write a short response first.'); return; }
  const scriptureEnabled = !!document.getElementById('mercyAttachScripture')?.checked;
  const scriptureRef = scriptureEnabled ? (document.getElementById('mercyScriptureRef')?.value.trim() || '') : '';
  const scriptureText = scriptureEnabled ? (document.getElementById('mercyScriptureText')?.value.trim() || '') : '';
  if (scriptureRef && !scriptureText) { alert('Add verse text or remove the Scripture reference.'); return; }
  const friendUid = document.getElementById('mercyFriendSelect')?.value || null;
  const friendName = friendUid ? _selectedMercyFriendName() : null;
  const extraTagged = [...document.querySelectorAll('.mercy-extra-friend-select')]
    .map(sel => ({ uid: sel.value, name: sel.selectedOptions?.[0]?.dataset?.name || sel.selectedOptions?.[0]?.textContent || '' }))
    .filter(f => f.uid);
  const taggedMap = new Map();
  if (friendUid) taggedMap.set(friendUid, friendName);
  extraTagged.forEach(f => taggedMap.set(f.uid, f.name));
  const taggedFriendUids = [...taggedMap.keys()];
  const taggedFriendNames = [...taggedMap.values()].filter(Boolean);
  const btn = document.getElementById('mercySubmitBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Posting...'; }
  try {
    const ready = await waitForMerciesApi();
    if (!ready) {
      alert('Praises is still connecting. Try again in a moment.');
      return;
    }
    const post = {
      body,
      promptText: _currentMercyPromptText(),
      promptCategory: document.getElementById('mercyFriendEncouragement')?.checked ? 'Friend Encouragement' : 'Daily Praise',
      promptMode: _mercyPromptChoiceMode,
      photoMode: _mercyOriginalImageFile ? 'full' : null,
      imageAspectRatio: _mercyOriginalImageFile ? _mercyPhotoAspectRatio : null,
      scripture: scriptureText ? { ref: scriptureRef || 'Scripture', text: scriptureText } : null,
      scriptureCard: scriptureText ? {
        bg: document.getElementById('mercyScriptureBg')?.value || 'theme',
        font: document.getElementById('mercyScriptureFont')?.value || 'system',
        color: document.getElementById('mercyScriptureColor')?.value || '#123532'
      } : null,
      taggedFriendUid: friendUid,
      taggedFriendName: friendName,
      taggedFriendUids,
      taggedFriendNames,
      friendEncouragement: !!document.getElementById('mercyFriendEncouragement')?.checked
    };
    const authorName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Someone';
    const created = await window.Mercies.add(uid, authorName, _currentProfileAvatarValue(), friendsList, _mercyImageBlob, post);
    const id = typeof created === 'string' ? created : created?.id;
    if (!id) { alert('Could not post this Praise right now. Try again.'); return; }
    if (typeof created?.streakDays === 'number') {
      localStorage.setItem('mercyStreakDays', String(created.streakDays));
      localStorage.setItem('mercyLastPostDate', _localDateKey(new Date(created.createdAtMs || Date.now())));
      updatePraiseStreakUI();
    } else {
      markMercyPostedToday();
    }
    if (document.getElementById('mercySaveThis')?.checked) {
      await saveMercyToJournal(id, {
        id,
        ...post,
        authorUid: uid,
        imageUrl: created?.imageUrl || null,
        imagePath: created?.imagePath || null,
        imageDataUrl: _mercyImageDataUrl,
        createdAtMs: created?.createdAtMs || Date.now()
      });
    }
    if (post.friendEncouragement && taggedFriendUids.includes(_pendingMercyFriendEncouragement?.friendUid)) {
      clearPendingMercyFriendEncouragement(_pendingMercyFriendEncouragement.friendUid);
    }
    closeMercyComposer();
  } catch (e) {
    console.warn('submitMercyPost:', e);
    alert('Could not post this Praise right now. Try again.');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Post Praise'; }
  }
}

