function selectCommunityPostKind(kind) {
  _communityPostKind = kind || 'insight';
  document.querySelectorAll('.cpc-kind').forEach(btn => btn.classList.toggle('active', btn.dataset.kind === _communityPostKind));
}

function _parseCommunityVerseRef(input) {
  const raw = String(input || '').trim().replace(/\s+/g, ' ');
  const match = raw.match(/^(.+?)\s+(\d+):(\d+)$/);
  if (!match) return null;
  const wanted = match[1].toLowerCase().replace(/\./g, '');
  const books = window.RhemaEnglishBooks || [];
  const aliases = new Map();
  books.forEach(book => {
    aliases.set(book.name.toLowerCase(), book);
    aliases.set(book.name.toLowerCase().slice(0, 3), book);
    aliases.set(book.code.toLowerCase(), book);
  });
  aliases.set('john', books.find(b => b.code === 'JOH'));
  aliases.set('jn', books.find(b => b.code === 'JOH'));
  aliases.set('acts', books.find(b => b.code === 'ACT'));
  aliases.set('act', books.find(b => b.code === 'ACT'));
  const book = aliases.get(wanted);
  if (!book) return null;
  return { book, chapter: match[2], verse: match[3] };
}

async function updateCommunityPostVersePreview() {
  await loadRhemaScripts().catch(() => {});
  const preview = document.getElementById('communityPostVersePreview');
  const refInput = document.getElementById('communityPostRef')?.value || '';
  const version = document.getElementById('communityPostVersion')?.value || 'MSB';
  const parsed = _parseCommunityVerseRef(refInput);
  if (!parsed) {
    _communityPostVerse = null;
    if (preview) preview.textContent = 'Use a reference like John 3:16.';
    return;
  }
  const text = _rhemaEnglishText(parsed.book.code, parsed.chapter, parsed.verse, version);
  if (!text) {
    _communityPostVerse = null;
    if (preview) preview.textContent = `${parsed.book.name} ${parsed.chapter}:${parsed.verse} is not available in ${version}.`;
    return;
  }
  _communityPostVerse = {
    version,
    book: parsed.book.code,
    ref: `${parsed.book.name} ${parsed.chapter}:${parsed.verse}`,
    text
  };
  if (preview) preview.textContent = text;
}

function clearCommunityPostVerse() {
  _communityPostVerse = null;
  const ref = document.getElementById('communityPostRef');
  const preview = document.getElementById('communityPostVersePreview');
  if (ref) ref.value = '';
  if (preview) preview.textContent = 'No verse will be sent unless you type a reference like John 3:16 and preview it.';
}

async function submitCommunityPost() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  const body = document.getElementById('communityPostBody')?.value.trim() || '';
  const question = document.getElementById('communityPostQuestion')?.value.trim() || '';
  const linkUrl = document.getElementById('communityPostLink')?.value.trim() || '';
  if (!body && !question && !_communityPostVerse && !linkUrl) {
    alert('Add a thought, question, verse, or link first.');
    return;
  }
  const btn = document.getElementById('communityPostSubmitBtn');
  if (btn) { btn.disabled = true; btn.textContent = 'Posting...'; }
  const displayName = localStorage.getItem('authDisplayName') || localStorage.getItem('authUsername') || 'Someone';
  const avatar = _currentProfileAvatarValue();
  const id = await window.CommunityPosts?.add?.(uid, displayName, avatar, friendsList, {
    kind: _communityPostKind,
    body,
    question,
    linkUrl,
    verse: _communityPostVerse,
    alertFriends: !!document.getElementById('communityPostAlertFriends')?.checked
  });
  if (btn) { btn.disabled = false; btn.textContent = 'Post to Community'; }
  if (!id) {
    alert('Could not post right now. Try again.');
    return;
  }
  closeCommunityPostComposer();
}

async function reactCommunityPost(postId, emoji) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  await window.CommunityPosts?.react?.(postId, uid, emoji);
}

async function prayForCommunityPost(postId) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  await window.CommunityPosts?.pray?.(postId, uid);
}

function openCommunityComments(postId) {
  _sharedCommentsMode = 'community';
  _communityCommentsPostId = postId;
  const post = _communityPosts.find(p => p.id === postId);
  const title = document.getElementById('communityCommentsTitle');
  if (title) title.textContent = post?.verse?.ref || _communityKindMeta(post?.kind).label || 'Post Comments';
  const input = document.getElementById('communityCommentInput');
  if (input) input.value = '';
  document.getElementById('communityCommentsModal')?.classList.add('open');
  const list = document.getElementById('communityCommentsList');
  if (list) list.innerHTML = '<p class="study-board-empty">Loading comments...</p>';
  if (_communityCommentsUnsub) _communityCommentsUnsub();
  _communityCommentsUnsub = window.CommunityPosts?.listenComments?.(postId, comments => {
    const el = document.getElementById('communityCommentsList');
    if (!el) return;
    if (!comments.length) {
      el.innerHTML = '<p class="community-comment-empty">No comments yet. Start the conversation.</p>';
      return;
    }
    el.innerHTML = comments.map(c => `<div class="community-comment-row">
      <span class="community-comment-avatar">${_renderAvatar(c.authorAvatar || 'person')}</span>
      <div><strong>${_lbEscape(c.authorName || 'Someone')}</strong><p>${_lbEscape(c.body || '')}</p><small>${_communityPostTime(c)}</small></div>
    </div>`).join('');
  }) || null;
}

function closeCommunityComments() {
  document.getElementById('communityCommentsModal')?.classList.remove('open');
  if (_communityCommentsUnsub) { _communityCommentsUnsub(); _communityCommentsUnsub = null; }
  _communityCommentsPostId = null;
}

function closeSharedPostComments() {
  if (_sharedCommentsMode === 'mercy') closeMercyComments();
  else closeCommunityComments();
}

function submitSharedPostComment() {
  if (_sharedCommentsMode === 'mercy') return submitMercyComment();
  return submitCommunityComment();
}

async function submitCommunityComment() {
  const uid = window.Auth?.getCurrentUser()?.uid;
  const input = document.getElementById('communityCommentInput');
  const text = input?.value.trim() || '';
  if (!uid || !_communityCommentsPostId || !text) return;
  const btn = document.getElementById('communityCommentSubmit');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending...'; }
  const ok = await window.CommunityPosts?.addComment?.(_communityCommentsPostId, uid, text);
  if (btn) { btn.disabled = false; btn.textContent = 'Comment'; }
  if (ok && input) input.value = '';
}

function openCommunityReactions(postId) {
  _sharedCommentsMode = 'community';
  const post = _communityPosts.find(p => p.id === postId);
  const people = document.getElementById('communityReactionPeople');
  if (!post || !people) return;
  const entries = Object.values(post.reactions || {}).map(value =>
    typeof value === 'string'
      ? { emoji: value, name: 'Friend', avatar: 'person' }
      : { emoji: value?.emoji, name: value?.name || 'Friend', avatar: value?.avatar || 'person' }
  ).filter(r => r.emoji);
  people.innerHTML = entries.length
    ? entries.map(r => `<div class="community-reaction-person"><span>${_renderAvatar(r.avatar)}</span><strong>${_lbEscape(r.name)}</strong><em>${r.emoji}</em></div>`).join('')
    : '<p class="community-comment-empty">No reactions yet.</p>';
  document.getElementById('communityReactionsModal')?.classList.add('open');
}

function closeCommunityReactions() {
  document.getElementById('communityReactionsModal')?.classList.remove('open');
}

function closeSharedPostReactions() {
  document.getElementById('communityReactionsModal')?.classList.remove('open');
}

async function deleteCommunityPost(postId) {
  const uid = window.Auth?.getCurrentUser()?.uid;
  if (!uid) return;
  _communityPosts = _communityPosts.filter(p => p.id !== postId);
  _renderCommunityPosts();
  const ok = await window.CommunityPosts?.delete?.(postId, uid);
  if (!ok) _startCommunityPosts();
}

let _lbEntryCache = {};

function _renderLbEntries(listEl, entries, field, myUid) {
  if (!entries.length) {
    listEl.innerHTML = '<p class="lb-empty">No entries yet — be the first!</p>';
    return;
  }
  entries.forEach(e => { _lbEntryCache[e.id] = e; });
  listEl.innerHTML = entries.map((e, i) => {
    const rank = i + 1;
    const isMe = e.id === myUid;
    const val = field === "xp"
      ? `${(e.xp || 0).toLocaleString()} XP`
      : field === "bestScore"
      ? `${e.bestScore || 0} correct`
      : `${e.streak || 0} day streak`;
    return `<div class="lb-entry${rank <= 3 ? " lb-top-" + rank : ""}${isMe ? " lb-me" : ""}" onclick="showLbUserInfo('${_lbEscape(e.id)}')">
      ${_rankBadgeHtml(rank)}
      ${_lbAvatarHtml(e)}
      <span class="lb-name">${_lbEscape(e.name)}</span>
      <span class="lb-value">${val}</span>
    </div>`;
  }).join("");
}

function _renderXPBoard() {
  const podiumEl = document.getElementById("lbPodiumXP");
  const listEl   = document.getElementById("lbListXP");
  const joinEl   = document.getElementById("lbJoinXP");
  const uid = window.LB?.getUserId();
  podiumEl.innerHTML = '<p class="lb-loading">Loading…</p>';
  listEl.innerHTML = "";

  if (!window.LB) { podiumEl.innerHTML = '<p class="lb-empty">Connecting…</p>'; return; }

  const t = setTimeout(() => {
    if (podiumEl.querySelector(".lb-loading"))
      podiumEl.innerHTML = '<p class="lb-empty">Couldn\'t load — <button class="lb-retry-btn" onclick="_renderXPBoard()">Retry</button></p>';
  }, 8000);

  _lbUnsub = window.LB.listenBoard("xp_board", "xp", (entries, err) => {
    clearTimeout(t);
    if (err) { podiumEl.innerHTML = '<p class="lb-empty">Couldn\'t load — <button class="lb-retry-btn" onclick="_renderXPBoard()">Retry</button></p>'; return; }
    _renderPodiumBoard(podiumEl, listEl, entries, "xp", uid);
    updateProfileBadges();
  });

  joinEl.innerHTML = "";
}

function _renderScholarBoard() {
  const podiumEl = document.getElementById("lbPodiumScholar");
  const listEl   = document.getElementById("lbListScholar");
  const joinEl   = document.getElementById("lbJoinScholar");
  const uid = window.LB?.getUserId();
  podiumEl.innerHTML = '<p class="lb-loading">Loading…</p>';
  listEl.innerHTML = "";

  if (!window.LB) { podiumEl.innerHTML = '<p class="lb-empty">Connecting…</p>'; return; }

  window.LB.getBoard("scholar_board", "bestScore").then(entries => {
    _renderPodiumBoard(podiumEl, listEl, entries, "bestScore", uid);
    updateProfileBadges();
  }).catch(() => {
    podiumEl.innerHTML = '<p class="lb-empty">Couldn\'t load — <button class="lb-retry-btn" onclick="_renderScholarBoard()">Retry</button></p>';
  });

  if (window.LB.isScholarJoined()) {
    const best = localStorage.getItem("lbScholarBest") || "0";
    joinEl.innerHTML = `<p class="lb-joined-note"><span class="material-symbols-outlined">star</span> Your best: <strong>${best} correct</strong></p>
      <button class="lb-join-btn lb-retake-btn" onclick="startScholarTest()">📖 Retake Scholar Test</button>`;
  } else {
    joinEl.innerHTML = `<button class="lb-join-btn" onclick="promptJoinScholar()">Join Scholar Board</button>`;
  }
}

function _renderPodiumBoard(podiumEl, listEl, entries, field, myUid) {
  if (!entries.length) {
    podiumEl.innerHTML = '<p class="lb-empty">No entries yet — be the first!</p>';
    listEl.innerHTML = "";
    return;
  }
  entries.forEach(e => { _lbEntryCache[e.id] = e; });

  const valStr = e => field === "xp"
    ? `${(e.xp || 0).toLocaleString()} XP`
    : `${e.bestScore || 0} correct`;

  // Podium order: 2nd left, 1st center, 3rd right
  const top = entries.slice(0, 3);
  const order = [top[1], top[0], top[2]].filter(Boolean);
  const ranks = top[1] ? [2, 1, 3] : top[0] ? [1, 3] : [1];

  podiumEl.innerHTML = `<div class="lb-podium">${order.map((e, i) => {
    const rank = ranks[i];
    const isMe = e.id === myUid;
    return `<div class="lb-pod-card lb-pod-${rank === 1 ? "first" : rank === 2 ? "second" : "third"}${isMe ? " lb-pod-me" : ""}" onclick="showLbUserInfo('${_lbEscape(e.id)}')">
      ${rank === 1 ? `<span class="lb-pod-crown material-symbols-outlined">emoji_events</span>` : ""}
      <div class="lb-pod-rank">${rank}</div>
      <div class="lb-pod-avatar">${_renderAvatar(e.avatar)}</div>
      <div class="lb-pod-name">${_lbEscape(e.name || "User")}</div>
      <div class="lb-pod-score">${valStr(e)}</div>
    </div>`;
  }).join("")}</div>`;

  const rest = entries.slice(3);
  listEl.innerHTML = rest.map((e, i) => {
    const isMe = e.id === myUid;
    return `<div class="lb-row${isMe ? " lb-row-me" : ""}" onclick="showLbUserInfo('${_lbEscape(e.id)}')">
      <span class="lb-row-rank">#${i + 4}</span>
      <span class="lb-row-avatar">${_renderAvatar(e.avatar)}</span>
      <span class="lb-row-name">${_lbEscape(e.name || "User")}</span>
      <span class="lb-row-score">${valStr(e)}</span>
    </div>`;
  }).join("");
}

