const HOME_RHEMA_TOPIC_RULES = [
  { any: ['noah','ark','flood'], refs: [['GEN','6'], ['GEN','7'], ['GEN','8'], ['GEN','9']], boost: 150 },
  { any: ['babel','tower'], refs: [['GEN','11']], boost: 150 },
  { any: ['burning','bush'], refs: [['EXO','3']], boost: 150 },
  { any: ['red','sea','pharaoh'], refs: [['EXO','14']], boost: 150 },
  { any: ['commandments','sinai','tablets'], refs: [['EXO','20']], boost: 150 },
  { any: ['manna','wilderness','bread'], refs: [['EXO','16']], boost: 95 },
  { any: ['david','goliath','giant'], refs: [['1SA','17']], boost: 190 },
  { any: ['elijah','carmel','fire','prophets'], refs: [['1KI','18']], boost: 170 },
  { any: ['lion','lions','den','daniel'], refs: [['DAN','6']], boost: 190 },
  { any: ['dry','bones','valley'], refs: [['EZK','37']], boost: 170 },
  { any: ['jonah','fish','whale'], refs: [['JON','1'], ['JON','2']], boost: 175 },
  { any: ['esther','time','such'], refs: [['EST','4']], boost: 135 },
  { any: ['ruth','boaz','kinsman'], refs: [['RUT','2'], ['RUT','3'], ['RUT','4']], boost: 125 },
  { any: ['beatitudes','blessed','poor','meek'], refs: [['MAT','5']], boost: 140 },
  { any: ['lord','prayer','kingdom','daily'], refs: [['MAT','6'], ['LUK','11']], boost: 135 },
  { any: ['samaritan','neighbor','road'], refs: [['LUK','10']], boost: 170 },
  { any: ['prodigal','lost','son'], refs: [['LUK','15']], boost: 190 },
  { any: ['lost','sheep'], refs: [['LUK','15'], ['MAT','18']], boost: 135 },
  { any: ['woman','well','living','water'], refs: [['JOH','4']], boost: 170 },
  { any: ['born','again','nicodemus'], refs: [['JOH','3']], boost: 170 },
  { any: ['lazarus','raise','dead','tomb'], refs: [['JOH','11']], boost: 180 },
  { any: ['feeding','five','thousand','loaves','fish'], refs: [['JOH','6'], ['MAT','14'], ['MAR','6'], ['LUK','9']], boost: 150 },
  { any: ['walking','water','storm'], refs: [['MAT','14'], ['MAR','6'], ['JOH','6']], boost: 140 },
  { any: ['transfiguration','mountain','moses','elijah'], refs: [['MAT','17'], ['MAR','9'], ['LUK','9']], boost: 160 },
  { any: ['temple','tables','money','changers'], refs: [['JOH','2'], ['MAT','21'], ['MAR','11'], ['LUK','19']], boost: 150 },
  { any: ['fruit','spirit','love','joy','peace'], refs: [['GAL','5']], boost: 150 },
  { any: ['love','patient','kind'], refs: [['1CO','13']], boost: 170 },
  { any: ['armor','armour','god'], refs: [['EPH','6']], boost: 170 },
  { any: ['faith','works','dead'], refs: [['JAM','2']], boost: 150 },
  { any: ['anxious','worry','worried','birds','lilies'], refs: [['MAT','6']], boost: 150 },
  { any: ['peace','understanding','anxious'], refs: [['PHP','4']], boost: 145 },
  { any: ['new','heaven','earth','tears'], refs: [['REV','21']], boost: 150 }
];

function _homeRhemaEscape(text) {
  return String(text || '').replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  }[ch]));
}

function _homeRhemaNormalize(text) {
  let out = String(text || '').toLowerCase();
  out = out.replace(/[^a-z0-9\s:]/g, ' ');
  const aliases = [
    [/\bcephas\b/g, ' peter cephas '],
    [/\bpeter\b/g, ' peter cephas '],
    [/\bgentiles?\b/g, ' gentile gentiles nations uncircumcised '],
    [/\bget(?:ting)?\s+on\s+to\b/g, ' rebuke oppose correct confront '],
    [/\bcalled\s+out\b/g, ' rebuke oppose correct confront '],
    [/\bconfront(?:ed|ing)?\b/g, ' confront oppose rebuke '],
    [/\brebuk(?:e|ed|ing)\b/g, ' rebuke oppose correct '],
    [/\bact(?:ed|ing)?\b/g, ' conduct behavior hypocrisy '],
    [/\bhypocrit(?:e|es|ical|ically)?\b/g, ' hypocrisy hypocrite '],
    [/\bpaul\b/g, ' paul apostle i '],
    [/\bsaul\b/g, ' saul paul '],
    [/\bradshack\b/g, ' shadrach '],
    [/\bmishack\b/g, ' meshach '],
    [/\babendigo\b/g, ' abednego '],
    [/\babednigo\b/g, ' abednego '],
    [/\bshadrack\b/g, ' shadrach '],
    [/\bmeshack\b/g, ' meshach '],
    [/\bfiery\b/g, ' fire furnace flame burning '],
    [/\bfurnace\b/g, ' furnace fire flame burning '],
    [/\bwhale\b/g, ' fish great fish jonah '],
    [/\bgiants?\b/g, ' giant goliath '],
    [/\bscared\b/g, ' afraid fear anxious '],
    [/\bworried\b/g, ' worry anxious care '],
    [/\bworry(?:ing)?\b/g, ' worry anxious care '],
    [/\banxiety\b/g, ' anxious worry care '],
    [/\bforgive(?:n|ness)?\b/g, ' forgive forgiveness mercy debt '],
    [/\bpraying\b/g, ' pray prayer '],
    [/\bneighbor\b/g, ' neighbor samaritan mercy '],
    [/\bnicodemous\b/g, ' nicodemus '],
    [/\blazurus\b/g, ' lazarus '],
    [/\bresurection\b/g, ' resurrection raise dead '],
    [/\bholy\s+spirit\b/g, ' spirit holy spirit '],
    [/\btablets\b/g, ' commandments tablets law '],
    [/\bten\s+commandments\b/g, ' commandments tablets law sinai '],
    [/\bmoney\s+changers?\b/g, ' money changers temple tables '],
    [/\blord'?s\s+prayer\b/g, ' lord prayer kingdom daily bread '],
    [/\bfruit\s+of\s+the\s+spirit\b/g, ' fruit spirit love joy peace patience kindness goodness faithfulness gentleness self control ']
  ];
  aliases.forEach(([pattern, replacement]) => { out = out.replace(pattern, replacement); });
  return out.replace(/\s+/g, ' ').trim();
}

function _homeRhemaTokens(query) {
  return _homeRhemaNormalize(query)
    .split(' ')
    .map(t => t.trim())
    .filter(t => t.length > 2 && !HOME_RHEMA_STOPWORDS.has(t));
}

async function _ensureHomeRhemaSearchIndex() {
  if (_homeRhemaSearchIndex) return _homeRhemaSearchIndex;
  await loadRhemaScripts();
  const data = window.RhemaMSB || {};
  _homeRhemaSearchIndex = [];
  RHEMA_BOOK_ORDER.forEach((book) => {
    const chapters = data[book] || {};
    Object.keys(chapters).forEach((chapter) => {
      const verses = chapters[chapter] || {};
      Object.keys(verses).forEach((verse) => {
        const text = verses[verse] || '';
        if (!text) return;
        const ref = `${_rhemaBookName(book)} ${chapter}:${verse}`;
        const norm = _homeRhemaNormalize(`${ref} ${RHEMA_BOOK_ABBR[book] || ''} ${text}`);
        const tokenSet = new Set(norm.split(' ').filter(t => t.length > 2 && !HOME_RHEMA_STOPWORDS.has(t)));
        _homeRhemaSearchIndex.push({ book, chapter: String(chapter), verse: String(verse), ref, text, norm, tokenSet });
      });
    });
  });
  return _homeRhemaSearchIndex;
}

function _homeRhemaEditDistance(a, b, max = 2) {
  if (!a || !b) return max + 1;
  if (a === b) return 0;
  if (Math.abs(a.length - b.length) > max) return max + 1;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const curr = [i];
    let rowMin = curr[0];
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
      rowMin = Math.min(rowMin, curr[j]);
    }
    if (rowMin > max) return max + 1;
    prev = curr;
  }
  return prev[b.length];
}

function _homeRhemaFuzzyTokenScore(token, entry) {
  if (!entry.tokenSet || token.length < 5) return 0;
  let best = 0;
  entry.tokenSet.forEach((candidate) => {
    if (best >= 5) return;
    if (candidate.length < 5 || Math.abs(candidate.length - token.length) > 2) return;
    const dist = _homeRhemaEditDistance(token, candidate, 2);
    if (dist === 1) best = Math.max(best, 5);
    else if (dist === 2 && token.length >= 7) best = Math.max(best, 3);
  });
  return best;
}

function _homeRhemaDirectRef(query) {
  const raw = String(query || '').toLowerCase().replace(/\s+/g, ' ').trim();
  if (!raw) return null;
  const aliasMatch = raw.match(/\b([1-3]?\s?[a-z]+)\s+(\d{1,3})(?::(\d{1,3}))?\b/);
  if (aliasMatch) {
    const alias = aliasMatch[1].replace(/\s+/g, '');
    const numberedAlias = aliasMatch[1].replace(/\s+/, '');
    const code = HOME_RHEMA_REF_ALIASES[alias] || HOME_RHEMA_REF_ALIASES[numberedAlias];
    if (code) return { book: code, chapter: aliasMatch[2], verse: aliasMatch[3] || '1' };
  }
  const names = [];
  Object.entries(RHEMA_BOOK_NAMES).forEach(([code, name]) => {
    names.push([code, name.toLowerCase()]);
    names.push([code, (RHEMA_BOOK_ABBR[code] || '').toLowerCase()]);
  });
  names.sort((a, b) => b[1].length - a[1].length);
  for (const [code, name] of names) {
    if (!name) continue;
    const safe = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = raw.match(new RegExp(`\\b${safe}\\s+(\\d{1,3})(?::(\\d{1,3}))?\\b`));
    if (match) return { book: code, chapter: match[1], verse: match[2] || '1' };
  }
  return null;
}

function _homeRhemaTopicBoost(normQuery, entry) {
  let score = 0;
  const has = (word) => normQuery.includes(word);
  const inRef = (book, chapter, verses) => entry.book === book && entry.chapter === String(chapter) && (!verses || verses.includes(entry.verse));
  HOME_RHEMA_TOPIC_RULES.forEach((rule) => {
    const hits = rule.any.filter(term => has(term)).length;
    if (!hits) return;
    const matchesRef = rule.refs.some(([book, chapter, verses]) => inRef(book, chapter, verses));
    if (!matchesRef) return;
    score += rule.boost + Math.min(hits, 4) * 18;
  });

  if ((has('paul') || has('apostle')) && (has('peter') || has('cephas')) && (has('gentile') || has('uncircumcised') || has('hypocrisy') || has('rebuke') || has('oppose') || has('confront'))) {
    if (inRef('GAL', 2, ['11','12','13','14'])) score += 320;
    else if (entry.book === 'GAL' && entry.chapter === '2') score += 90;
  }
  if ((has('damascus') || has('road')) && (has('saul') || has('paul'))) {
    if (entry.book === 'ACT' && entry.chapter === '9') score += 70;
  }
  if ((has('prodigal') || has('lost')) && has('son')) {
    if (entry.book === 'LUK' && entry.chapter === '15') score += 70;
  }
  if ((has('armor') || has('armour')) && has('god')) {
    if (entry.book === 'EPH' && entry.chapter === '6') score += 70;
  }
  if ((has('faith') && has('works')) || has('dead')) {
    if (entry.book === 'JAM' && entry.chapter === '2') score += 55;
  }
  if ((has('shadrach') || has('meshach') || has('abednego')) && (has('furnace') || has('fire') || has('flame') || has('burning') || has('nebuchadnezzar'))) {
    if (entry.book === 'DAN' && entry.chapter === '3') score += 220;
  }
  return score;
}

function _scoreHomeRhemaEntry(query, tokens, entry, directRef) {
  let score = 0;
  if (directRef && entry.book === directRef.book && entry.chapter === directRef.chapter) {
    score += entry.verse === directRef.verse ? 200 : 25;
  }
  let matchedTokens = 0;
  tokens.forEach((token, idx) => {
    const first = entry.norm.indexOf(token);
    if (first === -1) {
      const fuzzy = _homeRhemaFuzzyTokenScore(token, entry);
      if (fuzzy > 0) matchedTokens++;
      score += fuzzy;
      return;
    }
    matchedTokens++;
    score += first < 30 ? 13 : 7;
    if (entry.norm.includes(` ${token} `)) score += 3;
    if (idx > 0 && entry.norm.includes(`${tokens[idx - 1]} ${token}`)) score += 8;
  });
  score += _homeRhemaTopicBoost(_homeRhemaNormalize(query), entry);
  if (tokens.length >= 2) score += Math.round((matchedTokens / tokens.length) * 24);
  if (matchedTokens >= 3) score += 18;
  if (tokens.length && tokens.every(token => entry.norm.includes(token) || _homeRhemaFuzzyTokenScore(token, entry) > 0)) score += 20;
  return score;
}

function _renderHomeRhemaSearchResults(items, status) {
  const target = document.getElementById('homeRhemaSearchResults');
  if (!target) return;
  if (status) {
    target.innerHTML = `<div class="home-rhema-search-status">${_homeRhemaEscape(status)}</div>`;
    return;
  }
  target.innerHTML = items.map((item, index) => `
    <button class="home-rhema-result" type="button" onclick="openHomeRhemaResult(${index})">
      <strong>${_homeRhemaEscape(item.ref)}</strong>
      <span>${_homeRhemaEscape(item.text)}</span>
    </button>
  `).join('');
}

function _syncHomeRhemaSearchClear(query = '') {
  document.getElementById('homeRhemaSearchClear')?.classList.toggle('hidden', !String(query || '').trim());
}

function homeRhemaSearch(value) {
  clearTimeout(_homeRhemaSearchTimer);
  const query = String(value || '').trim();
  _syncHomeRhemaSearchClear(query);
  if (!query) {
    _homeRhemaResults = [];
    _renderHomeRhemaSearchResults([]);
    return;
  }
  if (query.length < 3) {
    _homeRhemaResults = [];
    _renderHomeRhemaSearchResults([], 'Keep typing to search Rhema.');
    return;
  }
  _renderHomeRhemaSearchResults([], 'Searching Rhema...');
  _homeRhemaSearchTimer = setTimeout(async () => {
    try {
      const index = await _ensureHomeRhemaSearchIndex();
      const tokens = _homeRhemaTokens(query);
      const directRef = _homeRhemaDirectRef(query);
      const ranked = index
        .map(entry => ({ ...entry, score: _scoreHomeRhemaEntry(query, tokens, entry, directRef) }))
        .filter(entry => entry.score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, 5);
      _homeRhemaResults = ranked;
      _renderHomeRhemaSearchResults(ranked, ranked.length ? '' : 'No close match yet.');
    } catch (err) {
      _homeRhemaResults = [];
      _renderHomeRhemaSearchResults([], 'Rhema search could not load.');
    }
  }, 220);
}

function clearHomeRhemaSearch() {
  clearTimeout(_homeRhemaSearchTimer);
  _homeRhemaResults = [];
  const input = document.getElementById('homeRhemaSearchInput');
  if (input) input.value = '';
  _syncHomeRhemaSearchClear('');
  _renderHomeRhemaSearchResults([]);
  input?.focus();
}

// ── Inline home search (collapses to a magnifier next to the greeting) ───────
let _homeSearchInteracting = false;

function toggleHomeSearch(event) {
  event?.stopPropagation?.();
  const wrap = document.getElementById('homeInlineSearch');
  if (!wrap) return;
  if (wrap.classList.contains('open')) { closeHomeSearch(); return; }
  _initHomeSearchBehavior();
  wrap.classList.add('open');
  // Focus inside the tap gesture so the keyboard opens right away
  document.getElementById('homeRhemaSearchInput')?.focus({ preventScroll: true });
}

function closeHomeSearch() {
  const wrap = document.getElementById('homeInlineSearch');
  if (!wrap || !wrap.classList.contains('open')) return;
  wrap.classList.remove('open');
  clearTimeout(_homeRhemaSearchTimer);
  _homeRhemaResults = [];
  const input = document.getElementById('homeRhemaSearchInput');
  if (input) { input.value = ''; input.blur(); }
  _syncHomeRhemaSearchClear('');
  _renderHomeRhemaSearchResults([]);
}

function _initHomeSearchBehavior() {
  const input = document.getElementById('homeRhemaSearchInput');
  if (!input || input._homeSearchInit) return;
  input._homeSearchInit = true;
  // Taps on results or inside the pill (clear button) shouldn't count as
  // dismissing the keyboard — only a true blur closes the search.
  const markInteraction = () => {
    _homeSearchInteracting = true;
    setTimeout(() => { _homeSearchInteracting = false; }, 600);
  };
  document.getElementById('homeRhemaSearchResults')?.addEventListener('pointerdown', markInteraction);
  document.querySelector('#homeInlineSearch .his-pill')?.addEventListener('pointerdown', e => {
    if (e.target !== input) markInteraction();
  });
  input.addEventListener('blur', () => {
    setTimeout(() => {
      if (_homeSearchInteracting || document.activeElement === input) return;
      closeHomeSearch();
    }, 140);
  });
}

function openHomeRhemaTopResult() {
  if (_homeRhemaResults[0]) openHomeRhemaResult(0);
}

async function openHomeRhemaResult(index) {
  const result = _homeRhemaResults[index];
  if (!result) return;
  await showRhema();
  _rhemaTextMode = 'majority';
  _syncRhemaEnglishAlias();
  _rhemaBook = result.book;
  _rhemaChapter = String(result.chapter);
  _rhemaVerse = String(result.verse);
  _rhemaFullChapter = true;
  _rhemaShowEnglish = true;
  _rhemaVerseFocus = true;
  _rhemaGreekOnly = false;
  _rhemaSyntaxMode = false;
  _rhemaHighlightStrongs = null;
  syncRhemaPicker();
  _syncRhemaChapterUi();
  renderRhemaVerse();
  updateRhemaSwapVisibility();
  const scrollToSelectedVerse = () => {
    const body = document.querySelector('#rhemaModal .rhema-body');
    const englishDisplay = document.getElementById('rhemaEnglishDisplay');
    const visibleDisplay = _rhemaShowEnglish && englishDisplay && !englishDisplay.classList.contains('hidden')
      ? englishDisplay
      : document.getElementById('rhemaVerseDisplay');
    const target = visibleDisplay?.querySelector(`.rhema-chapter-block[data-verse="${_rhemaVerse}"]`);
    if (body && target) {
      const top = Math.max(0, _rhemaBlockScrollTop(body, target) - 12);
      body.scrollTo ? body.scrollTo({ top, behavior: 'auto' }) : (body.scrollTop = top);
    }
  };
  requestAnimationFrame(scrollToSelectedVerse);
  setTimeout(scrollToSelectedVerse, 180);
}

function isRhemaOTBook(bookCode) {
  return RHEMA_OT_BOOK_ORDER.includes(bookCode);
}

function isRhemaNTBook(bookCode) {
  return RHEMA_NT_BOOK_ORDER.includes(bookCode);
}

function getCurrentOriginalLanguageLayer(bookCode = _rhemaBook) {
  if (isRhemaOTBook(bookCode)) return _rhemaOTLayer === 'lxx' ? 'lxx' : 'hebrew';
  return 'nt-greek';
}

function setRhemaOTLayer(layer) {
  _rhemaOTLayer = layer === 'lxx' ? 'lxx' : 'hebrew';
  localStorage.setItem('rhemaOTLayer', _rhemaOTLayer);
  closeRhemaSheet();
  _syncWheelState();
  _syncToolWandIndicator();
  renderCurrentRhemaOriginalText();
}

function _rhemaLayerForBook(bookCode = _rhemaBook) {
  return getCurrentOriginalLanguageLayer(bookCode);
}

function _ensureRhemaBibleData() {
  if (!window.RhemaNT) return window.RhemaBible || null;
  // Keep a metadata shell for legacy callers. The active OT text is chosen by
  // getCurrentRhemaTextDataset(), not by merging every original-language layer.
  const lxx = window.RhemaLXX || { books: [], names: {}, text: {} };
  const hebrew = window.RhemaHebrewOT || { books: [], names: {}, text: {} };
  window.RhemaBible = {
    books: [...(hebrew.books?.length ? hebrew.books : lxx.books || []), ...(window.RhemaNT.books || RHEMA_NT_BOOK_ORDER)],
    names: { ...(lxx.names || {}), ...(hebrew.names || {}), ...(window.RhemaNT.names || {}) },
    text: { ...(hebrew.text || {}), ...(window.RhemaNT.text || {}) },
    _hasHebrew: !!window.RhemaHebrewOT,
    _hasLXX: !!window.RhemaLXX,
  };
  return window.RhemaBible;
}

function _rhemaData() {
  return _ensureRhemaBibleData();
}

function getCurrentRhemaTextDataset(bookCode = _rhemaBook) {
  if (isRhemaOTBook(bookCode)) {
    return _rhemaOTLayer === 'lxx' ? window.RhemaLXX : window.RhemaHebrewOT;
  }
  if (_rhemaTextMode === 'critical' && window.RhemaCriticalNT?.text) return window.RhemaCriticalNT;
  return window.RhemaNT;
}

function getCurrentRhemaLexicon(layer = getCurrentOriginalLanguageLayer()) {
  return layer === 'hebrew' ? (window.RhemaHebrewLexicon || {}) : (window.RhemaLexicon || {});
}

function getCurrentRhemaOccurrences(strongs, layer = getCurrentOriginalLanguageLayer()) {
  const store = layer === 'hebrew'
    ? window.RhemaHebrewOcc
    : layer === 'lxx'
      ? window.RhemaLXXOcc
      : window.RhemaOcc;
  return store?.[strongs] || null;
}

function _rhemaText() {
  _ensureRhemaBibleData();
  const otText = _rhemaOTLayer === 'lxx' ? (window.RhemaLXX?.text || {}) : (window.RhemaHebrewOT?.text || {});
  const ntText = _rhemaTextMode === 'critical' && window.RhemaCriticalNT?.text
    ? window.RhemaCriticalNT.text
    : (window.RhemaNT?.text || {});
  return { ...otText, ...ntText };
}

function _rhemaTextForMode(mode) {
  _ensureRhemaBibleData();
  const otText = _rhemaOTLayer === 'lxx' ? (window.RhemaLXX?.text || {}) : (window.RhemaHebrewOT?.text || {});
  const ntText = mode === 'critical' && window.RhemaCriticalNT?.text
    ? window.RhemaCriticalNT.text
    : (window.RhemaNT?.text || {});
  return { ...otText, ...ntText };
}

function _rhemaOtherTextMode() {
  return _rhemaTextMode === 'critical' ? 'majority' : 'critical';
}

function _rhemaBookName(code) {
  return _rhemaData()?.names?.[code] || RHEMA_BOOK_NAMES[code] || code;
}

function _rhemaBookOrder() {
  const text = _rhemaText();
  return RHEMA_BOOK_ORDER.filter(code => text[code]);
}

function _rhemaOccurrenceData(strongs) {
  return getCurrentRhemaOccurrences(strongs);
}

function renderCurrentRhemaOriginalText() {
  renderRhemaVerse();
}

// ── POS Highlight system ──────────────────────────────────────────────────────

let _rhemaPosHighlights  = new Set(); // active category keys
let _rhemaHighlightBarOn = false;     // whether the bar is visible
const RHEMA_ORIGINAL_NEGATIONS = new Set(['οὐ', 'ου', 'οὐκ', 'ουκ', 'οὐχ', 'ουχ', 'οὐχὶ', 'ουχι', 'οὐχί', 'οὔ', 'οὐδὲ', 'ουδε', 'οὐδέ', 'οὐδ', 'ουδ', 'οὐδεις', 'οὐδεὶς', 'ουδεις', 'μή', 'μὴ', 'μη', 'μηδὲ', 'μηδε', 'μηδέ', 'μηδείς', 'μηδεὶς', 'μηδεις', 'לֹא', 'לא', 'אַל', 'אל', 'בְּלִי']);

// Maps morph-code prefix → canonical highlight key
function normalizePosKey(morphCode) {
  if (!morphCode) return null;
  // Hebrew morphology codes (OSHB/MorphHB) start with 'H'
  if (morphCode[0] === 'H') {
    const segs = morphCode.slice(1).split('/');
    const pos = (segs[segs.length - 1] || '')[0];
    if (pos === 'V') return 'V';
    if (pos === 'N') return 'N';
    if (pos === 'A') return 'ADJ';
    if (pos === 'R') return 'PREP';
    if (pos === 'C') return 'CONJ';
    if (pos === 'D') return 'ADV';
    if (pos === 'P' || pos === 'S') return 'PRON';
    if (pos === 'T') return 'T';
    return null;
  }
  const raw = morphCode.split('-')[0];
  if (raw === 'A') return 'ADJ';
  if (raw === 'NEG') return 'NEG';
  // All pronoun subtypes → PRON
  if (['P','R','C','D','F','I','K','Q','X','PRON'].includes(raw)) return 'PRON';
  if (raw === 'RI') return 'N';            // proper noun → noun
  if (['PART','PRT','INJ','COND'].includes(raw)) return 'PART';
  return raw;
}

function _rhemaOriginalHighlightKey(word) {
  const surface = _stripGreekAccents(String(word?.[0] || '')).toLowerCase().replace(/[.,;··]/g, '');
  if (RHEMA_ORIGINAL_NEGATIONS.has(surface) || RHEMA_ORIGINAL_NEGATIONS.has(String(word?.[0] || ''))) return 'NEG';
  return normalizePosKey(word?.[2]);
}

const HIGHLIGHT_CATS = {
  V:    { color:'rgba(251,146,60,0.32)'  },
  N:    { color:'rgba(96,165,250,0.32)'  },
  ADJ:  { color:'rgba(74,222,128,0.32)'  },
  T:    { color:'rgba(167,139,250,0.32)' },
  PRON: { color:'rgba(251,113,133,0.32)' },
  PREP: { color:'rgba(45,212,191,0.32)'  },
  CONJ: { color:'rgba(250,204,21,0.32)'  },
  ADV:  { color:'rgba(253,186,116,0.32)' },
  NEG:  { color:'rgba(248,113,113,0.34)' },
  PART: { color:'rgba(148,163,184,0.34)' },
};

const RHEMA_ENGLISH_NLP_BUNDLE_VERSION = '3.0.104';
const RHEMA_ENGLISH_NEGATIONS = new Set(['no', 'not', "n't", 'never', 'neither', 'nor', 'nothing', 'none', 'without']);
const RHEMA_ENGLISH_POS_TO_HIGHLIGHT = {
  VERB: 'V',
  AUX: 'V',
  NOUN: 'N',
  PROPN: 'N',
  ADJ: 'ADJ',
  DET: 'T',
  PRON: 'PRON',
  ADP: 'PREP',
  SCONJ: 'CONJ',
  CCONJ: 'CONJ',
  ADV: 'ADV',
  PART: 'PART',
  INTJ: 'PART'
};

let _rhemaEnglishNlp = null;
let _rhemaEnglishNlpPromise = null;
let _rhemaEnglishHighlightRenderToken = 0;
const _rhemaEnglishPosCache = new Map();

function _rhemaEnglishHighlightActive() {
  return _rhemaShowEnglish && _rhemaHighlightBarOn && !_rhemaSyntaxMode;
}

function _rhemaEnglishHighlightSelected() {
  return _rhemaEnglishHighlightActive() && _rhemaPosHighlights.size > 0;
}

function _loadRhemaEnglishNlp() {
  if (_rhemaEnglishNlp) return Promise.resolve(_rhemaEnglishNlp);
  if (_rhemaEnglishNlpPromise) return _rhemaEnglishNlpPromise;
  _rhemaEnglishNlpPromise = new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-rhema-english-nlp="true"]');
    const finish = () => {
      const bundle = window.DiscipleBuilderWinkNLP;
      if (!bundle?.winkNLP || !bundle?.model) {
        reject(new Error('Rhema English NLP bundle did not initialize.'));
        return;
      }
      const nlp = bundle.winkNLP(bundle.model);
      _rhemaEnglishNlp = { nlp, its: nlp.its };
      resolve(_rhemaEnglishNlp);
    };
    if (existing) {
      if (window.DiscipleBuilderWinkNLP) finish();
      else existing.addEventListener('load', finish, { once: true });
      return;
    }
    const script = document.createElement('script');
    script.src = `assets/vendor/wink-nlp-en.js?v=${RHEMA_ENGLISH_NLP_BUNDLE_VERSION}`;
    script.async = true;
    script.dataset.rhemaEnglishNlp = 'true';
    script.onload = finish;
    script.onerror = () => reject(new Error('Unable to load Rhema English NLP bundle.'));
    document.head.appendChild(script);
  }).catch((error) => {
    console.warn('Rhema English highlighting unavailable:', error);
    _rhemaEnglishNlpPromise = null;
    throw error;
  });
  return _rhemaEnglishNlpPromise;
}

function _requestRhemaEnglishHighlightRender() {
  if (!_rhemaEnglishHighlightActive() || _rhemaEnglishNlp) return;
  const token = ++_rhemaEnglishHighlightRenderToken;
  _loadRhemaEnglishNlp().then(() => {
    if (token !== _rhemaEnglishHighlightRenderToken) return;
    updateHighlightToolbar();
    renderRhemaVerse();
  }).catch(() => updateHighlightToolbar());
}

function _requestRhemaEnglishSyntaxRender() {
  if (!_rhemaSyntaxMode || !_rhemaShowEnglish || _rhemaFullChapter || _rhemaEnglishNlp) return;
  const token = ++_rhemaEnglishHighlightRenderToken;
  _loadRhemaEnglishNlp().then(() => {
    if (token !== _rhemaEnglishHighlightRenderToken) return;
    renderRhemaVerse();
  }).catch(() => {});
}

function _rhemaEnglishPosKey(pos) {
  return RHEMA_ENGLISH_POS_TO_HIGHLIGHT[pos] || null;
}

function _rhemaEnglishTokenCat(token) {
  const value = String(token?.value || '').toLowerCase();
  if (_RHEMA_ENGLISH_NEGATIONS.has(value)) return 'NEG';
  return _rhemaEnglishPosKey(token?.pos);
}

function _rhemaEnglishRowsToCats(rows) {
  const cats = new Set();
  rows.forEach((token) => {
    const cat = _rhemaEnglishTokenCat(token);
    if (cat) cats.add(cat);
  });
  return cats;
}

function _rhemaEnglishTokenRows(text) {
  if (!_rhemaEnglishNlp || !text) return [];
  const doc = _rhemaEnglishNlp.nlp.readDoc(text);
  const rows = [];
  doc.tokens().each((token) => {
    rows.push({ value: token.out(), pos: token.out(_rhemaEnglishNlp.its.pos) });
  });
  return rows;
}

function _rhemaEnglishCacheKey(book, chapter, verse) {
  return `${_rhemaEnglishVersion()}|${book}|${chapter}|${verse}`;
}

function _rhemaEnglishVerseCats(book, chapter, verse, text) {
  if (!_rhemaEnglishNlp || !text) return new Set(Object.keys(HIGHLIGHT_CATS));
  const key = _rhemaEnglishCacheKey(book, chapter, verse);
  const cached = _rhemaEnglishPosCache.get(key);
  if (cached) return cached;
  const cats = _rhemaEnglishRowsToCats(_rhemaEnglishTokenRows(text));
  _rhemaEnglishPosCache.set(key, cats);
  return cats;
}

function _rhemaEnglishPresentCats() {
  const cats = new Set();
  if (!_rhemaEnglishNlp) return new Set(Object.keys(HIGHLIGHT_CATS));
  const addVerse = (verse) => {
    const text = _rhemaEnglishText(_rhemaBook, _rhemaChapter, verse);
    _rhemaEnglishVerseCats(_rhemaBook, _rhemaChapter, verse, text).forEach((cat) => cats.add(cat));
  };
  if (_rhemaFullChapter) {
    const chapterData = (_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {};
    Object.keys(chapterData).forEach(addVerse);
  } else {
    addVerse(_rhemaVerse);
  }
  return cats;
}

function _renderRhemaEnglishText(text, book = _rhemaBook, chapter = _rhemaChapter, verse = _rhemaVerse) {
  if (!text) return '';
  if (!_rhemaEnglishHighlightSelected() || !_rhemaEnglishNlp) return _escapeRhemaAttr(text);
  const rows = _rhemaEnglishTokenRows(text);
  _rhemaEnglishPosCache.set(_rhemaEnglishCacheKey(book, chapter, verse), _rhemaEnglishRowsToCats(rows));
  let cursor = 0;
  let html = '';
  const lowerText = text.toLowerCase();
  rows.forEach((token) => {
    const rawToken = String(token.value || '');
    if (!rawToken) return;
    const idx = lowerText.indexOf(rawToken.toLowerCase(), cursor);
    if (idx < cursor) return;
    html += _escapeRhemaAttr(text.slice(cursor, idx));
    const surface = text.slice(idx, idx + rawToken.length);
    const cat = _rhemaEnglishTokenCat(token);
    const color = cat && _rhemaPosHighlights.has(cat) ? HIGHLIGHT_CATS[cat]?.color : null;
    if (color) {
      html += `<span class="rhema-english-pos-highlight" data-cat="${cat}" style="background:${color}">${_escapeRhemaAttr(surface)}</span>`;
    } else {
      html += _escapeRhemaAttr(surface);
    }
    cursor = idx + rawToken.length;
  });
  html += _escapeRhemaAttr(text.slice(cursor));
  return html;
}

function _rhemaXrefKeyForVerse(book = _rhemaBook, chapter = _rhemaChapter, verse = _rhemaVerse) {
  return `${book} ${chapter}:${verse}`;
}

function _rhemaCuratedScriptureNotesForKey(key) {
  const version = typeof _rhemaEnglishVersion === 'function' ? _rhemaEnglishVersion() : 'MSB';
  const official = window.RhemaScriptureNotes?.[version]?.[key]
    || (version === 'MSB' ? window.RhemaScriptureNotes?.BSB?.[key] : null)
    || [];
  return official.map(item => ({
    ...item,
    label: item.label || 'Scripture citation footnote.',
    type: item.type || 'scripture citation',
    source: item.source || `${version} official footnote`
  }));
}

window.getRhemaScriptureNotesForKey = _rhemaCuratedScriptureNotesForKey;

function _rhemaExpandedCrossRefsForKey(key) {
  const raw = window.RhemaCrossRefs?.[key] || {};
  const labels = window.RhemaCrossRefLabels || [];
  const curated = _rhemaCuratedScriptureNotesForKey(key);
  const curatedRefs = new Set(curated.map(item => item.ref));
  const maps = [
    ['d', 'direct', 'Direct Cross References', 'menu_book'],
    ['t', 'themes', 'Themes', 'hub'],
    ['o', 'otNt', 'OT/NT Connections', 'link'],
    ['p', 'parallel', 'Parallel Ideas', 'sync_alt'],
    ['f', 'prophecy', 'Prophecy', 'workspace_premium']
  ];
  const groups = maps.map(([shortKey, keyName, title, icon]) => ({
    key: keyName,
    title,
    icon,
    refs: (raw[shortKey] || []).map(value => {
      const [ref, labelIndex] = String(value).split('|');
      return { ref, label: labels[Number(labelIndex)] || 'Related reference' };
    }).filter(item => !curatedRefs.has(item.ref))
  })).filter(group => group.refs.length);
  if (curated.length) {
    groups.unshift({
      key: 'quoted',
      title: 'Quoted / Alluded Scripture',
      icon: 'format_quote',
      refs: curated.map(item => ({
        ref: item.ref,
        label: item.label,
        type: item.type
      }))
    });
  }
  return groups;
}

function _rhemaInlineNoteHtml(book, chapter, verse) {
  const key = _rhemaXrefKeyForVerse(book, chapter, verse);
  const notes = _rhemaCuratedScriptureNotesForKey(key);
  if (!notes.length) return '';
  const title = `${notes.length} Scripture note${notes.length === 1 ? '' : 's'}`;
  return `<button class="rhema-reader-note-btn rhema-reader-note-btn-curated" onclick="event.stopPropagation();openRhemaReaderNote('${_escapeRhemaAttr(book)}','${_escapeRhemaAttr(chapter)}','${_escapeRhemaAttr(verse)}')" title="${title}" aria-label="${title}">
    <span class="material-symbols-outlined">sticky_note_2</span>
  </button>`;
}

function _rhemaDisplayRefFromKey(key) {
  if (typeof _xrefDisplay === 'function') return _xrefDisplay(key);
  const parsed = typeof _xrefParseRef === 'function' ? _xrefParseRef(key) : null;
  if (!parsed) return key;
  return `${_rhemaBookName(parsed.book)} ${parsed.chapter}:${parsed.verse}${parsed.endVerse ? '-' + parsed.endVerse : ''}`;
}

function _rhemaTextForRefKey(key) {
  if (typeof _xrefEnglishText === 'function') return _xrefEnglishText(key);
  const parsed = typeof _xrefParseRef === 'function' ? _xrefParseRef(key) : null;
  if (!parsed) return '';
  return _rhemaEnglishText(parsed.book, parsed.chapter, parsed.verse);
}

function openRhemaReaderNote(book, chapter, verse) {
  const key = _rhemaXrefKeyForVerse(book, chapter, verse);
  const notes = _rhemaCuratedScriptureNotesForKey(key);
  if (!notes.length) return;
  const existing = document.getElementById('rhemaReaderNoteSheet');
  if (existing) existing.remove();
  const sheet = document.createElement('div');
  sheet.id = 'rhemaReaderNoteSheet';
  sheet.className = 'rhema-reader-note-overlay';
  sheet.onclick = (event) => { if (event.target === sheet) closeRhemaReaderNote(); };
  sheet.innerHTML = `<div class="rhema-reader-note-card" onclick="event.stopPropagation()">
    <button class="sheet-x-close" onclick="closeRhemaReaderNote()"><span class="material-symbols-outlined">close</span></button>
    <div class="rhema-reader-note-head">
      <span class="material-symbols-outlined">sticky_note_2</span>
      <div><strong>${_escapeRhemaAttr(_rhemaDisplayRefFromKey(key))}</strong><small>Scripture note</small></div>
    </div>
    <p class="rhema-reader-note-source">${_escapeRhemaAttr(_rhemaEnglishText(book, chapter, verse))}</p>
    <div class="rhema-reader-note-actions">
      <button onclick="openRhemaReaderNoteTrail('${_escapeRhemaAttr(key)}','quoted')"><span class="material-symbols-outlined">route</span>Open as trail</button>
    </div>
    <div class="rhema-reader-note-groups">
      <section>
        <h4><span class="material-symbols-outlined">format_quote</span>Quoted / Alluded Scripture</h4>
        ${notes.map(item => `<button onclick="openRhemaReaderNoteRef('${_escapeRhemaAttr(key)}','${_escapeRhemaAttr(item.ref)}','quoted')">
          <strong>${_escapeRhemaAttr(_rhemaDisplayRefFromKey(item.ref))}</strong>
          <span>${_escapeRhemaAttr(_rhemaTextForRefKey(item.ref))}</span>
          <em><b>${_escapeRhemaAttr(item.type)}</b> - ${_escapeRhemaAttr(item.label)}</em>
        </button>`).join('')}
      </section>
    </div>
  </div>`;
  document.getElementById('rhemaModal')?.appendChild(sheet);
  requestAnimationFrame(() => sheet.classList.add('open'));
}

function openRhemaReaderNoteTrail(sourceRef, category = 'direct') {
  closeRhemaReaderNote();
  if (typeof openRhemaXrefTrailFromReader === 'function') {
    openRhemaXrefTrailFromReader(sourceRef, null, category);
    return;
  }
  const parsed = typeof _xrefParseRef === 'function' ? _xrefParseRef(sourceRef) : null;
  if (parsed) jumpToRhemaVerse(parsed.book, parsed.chapter, parsed.verse);
}

function openRhemaReaderNoteRef(sourceRef, ref, category = '') {
  const parsed = typeof _xrefParseRef === 'function' ? _xrefParseRef(ref) : null;
  if (!parsed) return;
  closeRhemaReaderNote();
  if (typeof openRhemaXrefTrailFromReader === 'function') {
    openRhemaXrefTrailFromReader(sourceRef, ref, category || null);
    return;
  }
  jumpToRhemaVerse(parsed.book, parsed.chapter, parsed.verse);
}

function closeRhemaReaderNote() {
  const sheet = document.getElementById('rhemaReaderNoteSheet');
  if (!sheet) return;
  sheet.classList.remove('open');
  setTimeout(() => sheet.remove(), 220);
}

function toggleRhemaHighlightBar() {
  _rhemaHighlightBarOn = !_rhemaHighlightBarOn;
  const bar = document.getElementById('rhemaHighlightBar');
  if (bar) bar.classList.toggle('hidden', !_rhemaHighlightBarOn);
  _syncWheelBtn('highlight', _rhemaHighlightBarOn);
  if (!_rhemaHighlightBarOn) {
    _rhemaPosHighlights.clear();
    renderRhemaVerse();
  } else {
    updateHighlightToolbar();
    _requestRhemaEnglishHighlightRender();
  }
}

function toggleRhemaHighlight(cat) {
  if (_rhemaEnglishHighlightActive()) {
    const present = _rhemaEnglishPresentCats();
    const hasMatch = present.has(cat);
    if (_rhemaPosHighlights.has(cat)) {
      _rhemaPosHighlights.delete(cat);
    } else {
      if (!hasMatch) {
        const btn = document.querySelector(`.rhema-hl-pill[data-cat="${cat}"]`);
        if (btn) { btn.classList.add('shake'); setTimeout(() => btn.classList.remove('shake'), 500); }
        return;
      }
      _rhemaPosHighlights.add(cat);
    }
    renderRhemaVerse();
    _requestRhemaEnglishHighlightRender();
    return;
  }

  let words;
  if (_rhemaFullChapter) {
    const chData = (_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {};
    words = Object.values(chData).flat();
  } else {
    words = (_rhemaText()[_rhemaBook] || {})[_rhemaChapter]?.[_rhemaVerse] || [];
  }
  const hasMatch = words.some(w => _rhemaOriginalHighlightKey(w) === cat);

  if (_rhemaPosHighlights.has(cat)) {
    _rhemaPosHighlights.delete(cat);
  } else {
    if (!hasMatch) {
      // shake the button and bail
      const btn = document.querySelector(`.rhema-hl-pill[data-cat="${cat}"]`);
      if (btn) { btn.classList.add('shake'); setTimeout(() => btn.classList.remove('shake'), 500); }
      return;
    }
    _rhemaPosHighlights.add(cat);
  }
  renderRhemaVerse();
}

function updateHighlightToolbar() {
  if (!_rhemaHighlightBarOn) return;
  if (_rhemaShowEnglish && !_rhemaSyntaxMode) {
    const present = _rhemaEnglishPresentCats();
    for (const cat of Object.keys(HIGHLIGHT_CATS)) {
      const btn = document.querySelector(`.rhema-hl-pill[data-cat="${cat}"]`);
      if (!btn) continue;
      const hasMatch = present.has(cat);
      const isActive = _rhemaPosHighlights.has(cat);
      btn.classList.toggle('hl-active',  isActive && hasMatch);
      btn.classList.toggle('hl-dimmed',  isActive && !hasMatch);
      btn.classList.toggle('hl-present', !isActive && hasMatch);
    }
    _requestRhemaEnglishHighlightRender();
    return;
  }
  let words;
  if (_rhemaFullChapter) {
    const chData = (_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {};
    words = Object.values(chData).flat();
  } else {
    words = (_rhemaText()[_rhemaBook] || {})[_rhemaChapter]?.[_rhemaVerse] || [];
  }
  for (const cat of Object.keys(HIGHLIGHT_CATS)) {
    const btn = document.querySelector(`.rhema-hl-pill[data-cat="${cat}"]`);
    if (!btn) continue;
    const hasMatch = words.some(w => _rhemaOriginalHighlightKey(w) === cat);
    const isActive = _rhemaPosHighlights.has(cat);
    btn.classList.toggle('hl-active',  isActive && hasMatch);
    btn.classList.toggle('hl-dimmed',  isActive && !hasMatch);
    btn.classList.toggle('hl-present', !isActive && hasMatch);
  }
}

// ── Morphology decoder ───────────────────────────────────────────────────────

const MORPH_POS = {
  N:'Noun', V:'Verb', T:'Article', ADJ:'Adjective', A:'Adjective',
  PREP:'Preposition', CONJ:'Conjunction', ADV:'Adverb', PART:'Particle',
  INJ:'Interjection', PRT:'Particle', COND:'Conditional Particle',
  HEB:'Hebrew/Aramaic', ARAM:'Aramaic', INF:'Infinitive',
  P:'Personal Pronoun', PRON:'Pronoun', R:'Relative Pronoun', RI:'Proper Noun',
  C:'Relative Pronoun', D:'Demonstrative Pronoun', F:'Reflexive Pronoun',
  I:'Interrogative Pronoun', K:'Correlative Pronoun', Q:'Correlative Pronoun',
  S:'Possessive Pronoun', X:'Indefinite Pronoun',
};
const MORPH_CASE = {
  N:{l:'Nominative', d:'subject of the verb'},
  G:{l:'Genitive',   d:'possession or relationship'},
  D:{l:'Dative',     d:'indirect object, location, or means'},
  A:{l:'Accusative', d:'direct object'},
  V:{l:'Vocative',   d:'direct address'},
};
const MORPH_NUM  = { S:'Singular', P:'Plural' };
const MORPH_GEN  = { M:'Masculine', F:'Feminine', N:'Neuter' };
const MORPH_TENSE = {
  P:{l:'Present',     d:'ongoing action'},
  I:{l:'Imperfect',   d:'ongoing past action'},
  F:{l:'Future',      d:'future action'},
  A:{l:'Aorist',      d:'completed past action'},
  R:{l:'Perfect',     d:'completed with present result'},
  L:{l:'Pluperfect',  d:'completed past with past result'},
  '2A':{l:'2nd Aorist', d:'completed past action (2nd form)'},
  '2R':{l:'2nd Perfect',d:'completed with present result (2nd form)'},
};
const MORPH_VOICE = {
  A:{l:'Active',         d:'subject performs the action'},
  M:{l:'Middle',         d:'subject acts for itself'},
  P:{l:'Passive',        d:'subject receives the action'},
  D:{l:'Middle/Deponent',d:'active meaning, middle form'},
  O:{l:'Middle-Passive', d:'middle or passive'},
  N:{l:'Middle or Passive',d:'voice ambiguous'},
  Q:{l:'Middle Deponent', d:'deponent with middle form'},
};
const MORPH_MOOD = {
  I:{l:'Indicative',  d:'stating a fact'},
  S:{l:'Subjunctive', d:'possibility or contingency'},
  O:{l:'Optative',    d:'wish or remote possibility'},
  M:{l:'Imperative',  d:'command'},
  N:{l:'Infinitive',  d:'verbal noun'},
  P:{l:'Participle',  d:'verbal adjective'},
};
const MORPH_PERSON = { '1':'1st Person', '2':'2nd Person', '3':'3rd Person' };

function decodeMorph(code) {
  if (!code) return [];
  const rows = [];

  const segs = code.split('-');
  const posRaw = segs[0];
  const vSegs  = segs.slice(1);

  // Indeclinable words — just show part of speech
  const INDECLINABLE = { PREP:1, CONJ:1, ADV:1, PART:1, INJ:1, PRT:1, COND:1, HEB:1, ARAM:1 };
  if (INDECLINABLE[posRaw]) {
    return [{ label:'Part of Speech', value: MORPH_POS[posRaw] || posRaw, desc:'' }];
  }

  // Detect 2nd aorist/perfect prefix on verb segments
  let tensePrefix = '';
  if (vSegs[0] && /^2[ARILP]/.test(vSegs[0])) {
    tensePrefix = '2';
    vSegs[0] = vSegs[0].substring(1);
  }

  const posLabel = MORPH_POS[posRaw];
  if (posLabel) rows.push({ label:'Part of Speech', value: posLabel, desc:'' });

  if (posRaw === 'V') {
    // Verb: [TVM]-[PN or CNG]
    const tvm = vSegs[0] || '';
    const pn  = vSegs[1] || '';
    const t = tensePrefix + tvm[0];
    const v = tvm[1];
    const m = tvm[2];
    const tObj = MORPH_TENSE[t] || MORPH_TENSE[tvm[0]];
    if (tObj) rows.push({ label:'Tense', value: tObj.l, desc: tObj.d });
    const vObj = MORPH_VOICE[v];
    if (vObj) rows.push({ label:'Voice', value: vObj.l, desc: vObj.d });
    const mObj = MORPH_MOOD[m];
    if (mObj) rows.push({ label:'Mood',  value: mObj.l, desc: mObj.d });
    if (m === 'N') {
      // infinitive — no person/number
    } else if (m === 'P') {
      // participle — case/number/gender
      const c = MORPH_CASE[pn[0]];
      const n = MORPH_NUM[pn[1]];
      const g = MORPH_GEN[pn[2]];
      if (c) rows.push({ label:'Case',   value: c.l, desc: c.d });
      if (n) rows.push({ label:'Number', value: n,   desc: '' });
      if (g) rows.push({ label:'Gender', value: g,   desc: '' });
    } else if (pn) {
      const person = MORPH_PERSON[pn[0]];
      const num    = MORPH_NUM[pn[1]];
      if (person) rows.push({ label:'Person', value: person, desc:'' });
      if (num)    rows.push({ label:'Number', value: num,    desc:'' });
    }

  } else if (posRaw === 'P' || posRaw === 'PRON') {
    // Personal pronoun: P-1AS (1st/2nd person: person+case+num) or P-APM (3rd: CNG)
    const seg = vSegs[0] || '';
    if (seg[0] === '1' || seg[0] === '2') {
      const person = MORPH_PERSON[seg[0]];
      const c = MORPH_CASE[seg[1]];
      const n = MORPH_NUM[seg[2]];
      if (person) rows.push({ label:'Person', value: person, desc:'' });
      if (c) rows.push({ label:'Case',   value: c.l, desc: c.d });
      if (n) rows.push({ label:'Number', value: n,   desc: '' });
    } else {
      const c = MORPH_CASE[seg[0]];
      const n = MORPH_NUM[seg[1]];
      const g = MORPH_GEN[seg[2]];
      if (c) rows.push({ label:'Case',   value: c.l, desc: c.d });
      if (n) rows.push({ label:'Number', value: n,   desc: '' });
      if (g) rows.push({ label:'Gender', value: g,   desc: '' });
    }

  } else if (posRaw === 'F') {
    // Reflexive pronoun: F-[person]CNG  e.g. F-1APM = 1st person Acc Pl Masc
    const seg = vSegs[0] || '';
    const person = MORPH_PERSON[seg[0]];
    const c = MORPH_CASE[seg[1]];
    const n = MORPH_NUM[seg[2]];
    const g = MORPH_GEN[seg[3]];
    if (person) rows.push({ label:'Person', value: person, desc:'' });
    if (c) rows.push({ label:'Case',   value: c.l, desc: c.d });
    if (n) rows.push({ label:'Number', value: n,   desc: '' });
    if (g) rows.push({ label:'Gender', value: g,   desc: '' });

  } else if (posRaw === 'S') {
    // Possessive pronoun/adjective: S-[person][possessor_num]CNG
    // e.g. S-1SNSM = 1st person Singular-possessor, Nom Sg Masc ("my")
    //      S-1PNSF = 1st person Plural-possessor, Nom Sg Fem ("our")
    const seg = vSegs[0] || '';
    const person  = MORPH_PERSON[seg[0]];
    const posNum  = MORPH_NUM[seg[1]];   // possessor's number
    const c = MORPH_CASE[seg[2]];
    const n = MORPH_NUM[seg[3]];
    const g = MORPH_GEN[seg[4]];
    if (person) rows.push({ label:'Person',   value: person,  desc:'' });
    if (posNum) rows.push({ label:'Possessor', value: posNum, desc:'' });
    if (c) rows.push({ label:'Case',   value: c.l, desc: c.d });
    if (n) rows.push({ label:'Number', value: n,   desc: '' });
    if (g) rows.push({ label:'Gender', value: g,   desc: '' });

  } else if (['N','T','ADJ','A','R','C','D','I','K','Q','X'].includes(posRaw)) {
    // Standard CNG: Noun, Article, Adjective, Relative/Demonstrative/Interrogative/
    // Correlative/Indefinite pronouns — vSegs[0] is CNG (ignore any trailing -K variant marker)
    const cng = vSegs[0] || '';
    // Indeclinable subtypes: PRI = proper noun, NUI = numeral, LI/OI = other indeclinables
    if (cng === 'PRI' || cng === 'NUI' || cng === 'LI' || cng === 'OI') {
      const label = cng === 'PRI' ? 'Proper Noun (Indeclinable)' :
                    cng === 'NUI' ? 'Numeral (Indeclinable)' : 'Indeclinable';
      rows.push({ label:'Form', value: label, desc:'' });
    } else {
      const c = MORPH_CASE[cng[0]];
      const n = MORPH_NUM[cng[1]];
      const g = MORPH_GEN[cng[2]];
      if (c) rows.push({ label:'Case',   value: c.l, desc: c.d });
      if (n) rows.push({ label:'Number', value: n,   desc: '' });
      if (g) rows.push({ label:'Gender', value: g,   desc: '' });
    }
  }

  return rows;
}

// ── Data loading ──────────────────────────────────────────────────────────────

function loadRhemaScripts() {
  return new Promise((resolve, reject) => {
    if (_rhemaLoaded) { resolve(); return; }
    if (_rhemaLoading) {
      const check = setInterval(() => {
        if (_rhemaLoaded) { clearInterval(check); resolve(); }
      }, 100);
      return;
    }
    _rhemaLoading = true;
    loadDeepLexiconSpine();
    let loaded = 0;
    const files = ['rhema-nt.js', 'rhema-critical.js', 'rhema-critical-fallbacks.js', 'rhema-ot-hebrew.js', 'rhema-hebrew-lexicon.js', 'rhema-lxx.js', 'rhema-lexicon.js', 'rhema-mm.js', 'rhema-msb.js', 'rhema-bsb.js', 'rhema-syntax.js', 'rhema-crossrefs.js', 'rhema-scripture-notes.js'];
    let failed = false;
    for (const file of files) {
      const s = document.createElement('script');
      s.src = file + '?v=' + (RHEMA_DATA_VERSIONS[file] || APP_VERSION);
      s.onload = () => {
        loaded++;
        if (loaded === files.length) { _syncRhemaEnglishAlias(); _ensureRhemaBibleData(); _rhemaLoaded = true; resolve(); }
      };
      s.onerror = () => {
        if (!failed) { failed = true; reject(new Error('Failed to load ' + file)); }
      };
      document.head.appendChild(s);
    }
  });
}

// ── Modal open/close ──────────────────────────────────────────────────────────

async function showRhema() {
  closeHomeSearch();
  _desktopCollapseNav();
  hideBottomNav();
  setNavActive('rhema');
  const modal = document.getElementById('rhemaModal');
  if (!modal) return;
  modal.classList.add('open');

  // Main entry opens as a plain-English chapter reader; the swap control takes
  // you into the Greek. Sandbox and sermon flows manage their own modes.
  const sermonMode = typeof _sermonRhemaMode !== 'undefined' && _sermonRhemaMode;
  if (!_studySandboxId && !sermonMode) {
    _rhemaFullChapter = true;
    _rhemaShowEnglish = true;
    _rhemaVerseFocus = false;
  }
  _syncRhemaChapterUi();

  const loading = document.getElementById('rhemaLoadingMsg');
  if (loading) loading.style.display = 'block';

  try {
    await loadRhemaScripts();
    if (loading) loading.style.display = 'none';
    initRhemaPicker();
    renderRhemaVerse();
    startRhemaCoach();
  } catch (e) {
    if (loading) loading.textContent = 'Failed to load data. Check your connection.';
  }
}

function _syncRhemaChapterUi() {
  const versionBtn = document.getElementById('rhemaEnglishVersionBtn');
  const versionLabel = document.getElementById('rhemaEnglishVersionLabel');
  if (versionBtn) {
    versionBtn.classList.toggle('active', _rhemaEnglishVersion() === 'BSB');
    versionBtn.title = `English translation: ${_rhemaEnglishLabel()}. Tap to switch to ${_rhemaEnglishVersion() === 'BSB' ? 'MSB' : 'BSB'}.`;
  }
  if (versionLabel) versionLabel.textContent = _rhemaEnglishLabel();
  document.getElementById('rhemaVersePillBtn')?.classList.toggle('hidden', _rhemaFullChapter);
  _syncRhemaLxxBtn();
}

function closeRhema(keepSandbox = false) {
  // If opened from sermon workshop, handle cleanup via sermon mode
  if (typeof _sermonRhemaMode !== 'undefined' && _sermonRhemaMode) {
    _closeSermonRhemaMode();
    return;
  }
  _saveRhemaPosition();
  if (typeof _closeRhemaXrefShell === 'function') _closeRhemaXrefShell();
  // If opened from a study sandbox, hide Save Verse button and update preview
  if (_studySandboxId) {
    document.getElementById('rhemaSaveToStudyBtn')?.classList.add('hidden');
    if (_studySandboxRhemaReturn) {
      _studySandboxRhemaReturn = false;
      // Update the sandbox Rhema position preview
      if (_activeSandboxStudy) {
        const uid = window.Auth?.getCurrentUser()?.uid;
        if (uid) {
          if (!_activeSandboxStudy.rhemaPositions) _activeSandboxStudy.rhemaPositions = {};
          _activeSandboxStudy.rhemaPositions[uid] = { book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse };
        }
        _updateSandboxRhemaPreview();
      }
      // Restore the main Rhema position AND modes so homescreen is unchanged
      if (_studySandboxMainRhemaPos) {
        _rhemaBook    = _studySandboxMainRhemaPos.book;
        _rhemaChapter = _studySandboxMainRhemaPos.chapter;
        _rhemaVerse   = _studySandboxMainRhemaPos.verse;
        _rhemaSyntaxMode = _studySandboxMainRhemaPos.syntaxMode || false;
        _rhemaShowEnglish    = _studySandboxMainRhemaPos.showEnglish    || false;
        _rhemaGreekOnly  = _studySandboxMainRhemaPos.greekOnly  || false;
        _studySandboxMainRhemaPos = null;
      }
    } else {
      // Tab-switch within study (keepSandbox=true) — reset modes for isolation
      _rhemaSyntaxMode = false;
      _rhemaShowEnglish = false;
      _rhemaGreekOnly = false;
    }
    if (!keepSandbox) _studySandboxId = null;
  }
  document.getElementById('rhemaModal')?.classList.remove('open');
  closeRhemaSheet();
  closeRhemaReaderNote();
  closeRhemaPickerSheet();
  document.querySelector('.rhema-sandbox-arrows')?.classList.remove('visible');
  _rhemaTrail = [];
  _rhemaTrailPos = -1;
  _rhemaHighlightStrongs = null;
  _rhemaVerseFocus = false;
  _rhemaPosHighlights.clear();
  _rhemaHighlightBarOn = false;
  document.getElementById('rhemaHighlightBar')?.classList.add('hidden');
  document.getElementById('rhemaHighlightToggleBtn')?.classList.remove('active');
  updateRhemaBreadcrumb();
  // Restore nav — determine active page from which screen is visible
  // Only restore bottom nav if not staying inside a sandbox session
  if (!_studySandboxId) {
    const activePage =
      document.getElementById('profilePage')?.classList.contains('active') ? 'profile' :
      document.getElementById('communityPage')?.classList.contains('active') ? 'community' : 'home';
    setNavActive(activePage);
    showBottomNav();
    _updateHomeContinueCard();
  }
}

function rhemaGoBack() {
  // In study sandbox: back button closes the study entirely (user navigates via tab bar)
  if (_studySandboxId) { closeStudySandbox(); return; }
  if (_rhemaTrail.length === 0) { closeRhema(); return; }
  // Move cursor back without removing any items
  if (_rhemaTrailPos === -1) {
    _rhemaTrailPos = _rhemaTrail.length - 1;
  } else if (_rhemaTrailPos > 0) {
    _rhemaTrailPos--;
  } else {
    closeRhema(); return;
  }
  const target = _rhemaTrail[_rhemaTrailPos];
  _rhemaBook = target.book;
  _rhemaChapter = target.chapter;
  _rhemaVerse = target.verse;
  _rhemaHighlightStrongs = target.strongs || null;
  _rhemaVerseFocus = true;
  closeRhemaSheet();
  syncRhemaPicker();
  renderRhemaVerse();
  updateRhemaBreadcrumb();
}

// ── Verse picker ──────────────────────────────────────────────────────────────

function initRhemaPicker() {
  if (!_rhemaData()) return;
  syncRhemaPicker();
}

function syncRhemaPicker() {
  const bookName = _rhemaBookName(_rhemaBook);
  const b = document.getElementById('rhemaPillBook');
  const v = document.getElementById('rhemaPillVerse');
  if (b) b.textContent = `${bookName} ${_rhemaChapter}`;
  if (v) v.textContent = 'v' + _rhemaVerse;
}

function openRhemaBookPicker() {
  closeRhemaPickerSheet();
  closeRhemaSheet();
  document.querySelector('.rhema-sandbox-arrows')?.classList.remove('visible');
  const overlay = document.getElementById('rhemaBookPickerOverlay');
  if (!overlay || !_rhemaData()) return;
  rhemaRenderBookList();
  overlay.classList.remove('hidden');
  document.getElementById('rhemaModal')?.classList.add('picker-open');
  initRhemaPickerSwipeDown('rhemaBookPickerOverlay');
}

function rhemaRenderBookList() {
  const list = document.getElementById('rhemaBookList');
  const title = document.getElementById('rhemaBookPickerTitle');
  const back = document.getElementById('rhemaBookPickerBack');
  const searchRow = document.querySelector('#rhemaBookPickerOverlay .rhema-picker-search-row');
  if (!list || !_rhemaData()) return;
  if (title) title.textContent = 'Select Book';
  back?.classList.add('hidden');
  searchRow?.classList.remove('hidden');
  const books = _rhemaBookOrder();
  const firstOT = books.find(c => RHEMA_OT_BOOK_ORDER.includes(c));
  const firstNT = books.find(c => RHEMA_NT_BOOK_ORDER.includes(c));
  list.innerHTML = books.map(code => {
    const name = _rhemaBookName(code);
    const sel  = code === _rhemaBook ? ' selected' : '';
    const isNT = RHEMA_NT_BOOK_ORDER.includes(code);
    let out = '';
    if (code === firstOT) out += '<div class="rhema-testament-sep" data-sep="OT">Old Testament</div>';
    if (code === firstNT) out += '<div class="rhema-testament-sep" data-sep="NT">New Testament</div>';
    out += `<div class="rhema-book-row${sel}" data-testament="${isNT ? 'NT' : 'OT'}" onclick="rhemaShowChaptersForBook('${code}')">
      <span class="material-symbols-outlined rhema-book-icon">menu_book</span>
      <span class="rhema-book-name">${name}</span>
      <span class="material-symbols-outlined rhema-book-check">check</span>
    </div>`;
    return out;
  }).join('');
  const search = document.getElementById('rhemaBookSearch');
  if (search) search.value = '';
  requestAnimationFrame(() => {
    const sel = list.querySelector('.selected');
    if (sel) list.scrollTop = sel.offsetTop - (list.clientHeight - sel.offsetHeight) / 2;
  });
}

function rhemaShowChaptersForBook(code) {
  const list = document.getElementById('rhemaBookList');
  const title = document.getElementById('rhemaBookPickerTitle');
  const back = document.getElementById('rhemaBookPickerBack');
  const searchRow = document.querySelector('#rhemaBookPickerOverlay .rhema-picker-search-row');
  if (!list || !_rhemaData()) return;
  const chapters = Object.keys(_rhemaText()[code] || {}).sort((a, b) => +a - +b);
  if (title) title.textContent = `${_rhemaBookName(code)} Chapters`;
  back?.classList.remove('hidden');
  searchRow?.classList.add('hidden');
  list.innerHTML = `<div class="rhema-book-chapter-grid">${chapters.map(ch => {
    const sel = code === _rhemaBook && ch === _rhemaChapter ? ' selected' : '';
    return `<button class="rhema-num-cell${sel}" onclick="rhemaSelectBookChapter('${code}','${ch}')">${ch}</button>`;
  }).join('')}</div>`;
  list.scrollTop = 0;
}

function openRhemaChapPicker() {
  closeRhemaPickerSheet();
  closeRhemaSheet();
  document.querySelector('.rhema-sandbox-arrows')?.classList.remove('visible');
  const overlay = document.getElementById('rhemaChapPickerOverlay');
  if (!overlay || !_rhemaData()) return;
  const chapters = Object.keys(_rhemaText()[_rhemaBook] || {}).sort((a,b) => +a-+b);
  document.getElementById('rhemaChapGrid').innerHTML = chapters.map(ch => {
    const sel = ch === _rhemaChapter ? ' selected' : '';
    return `<div class="rhema-num-cell${sel}" onclick="rhemaSelectChap('${ch}')">${ch}</div>`;
  }).join('');
  overlay.classList.remove('hidden');
  document.getElementById('rhemaModal')?.classList.add('picker-open');
  initRhemaPickerSwipeDown('rhemaChapPickerOverlay');
}

function openRhemaVersePicker() {
  closeRhemaPickerSheet();
  closeRhemaSheet();
  document.querySelector('.rhema-sandbox-arrows')?.classList.remove('visible');
  const overlay = document.getElementById('rhemaVersePickerOverlay');
  if (!overlay || !_rhemaData()) return;
  const verses = Object.keys((_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {}).sort((a,b) => +a-+b);
  document.getElementById('rhemaVerseGrid').innerHTML = verses.map(v => {
    const sel = v === _rhemaVerse ? ' selected' : '';
    return `<div class="rhema-num-cell${sel}" onclick="rhemaSelectVerse('${v}')">${v}</div>`;
  }).join('');
  overlay.classList.remove('hidden');
  document.getElementById('rhemaModal')?.classList.add('picker-open');
  initRhemaPickerSwipeDown('rhemaVersePickerOverlay');
}

function closeRhemaPickerSheet() {
  document.getElementById('rhemaModal')?.classList.remove('picker-open');
  ['rhemaBookPickerOverlay','rhemaChapPickerOverlay','rhemaVersePickerOverlay'].forEach(id => {
    const overlay = document.getElementById(id);
    if (!overlay) return;
    overlay.classList.add('hidden');
    const sheet = overlay.querySelector('.rhema-picker-sheet');
    if (sheet) { sheet.style.transform = ''; sheet.style.transition = ''; }
  });
  if (_studySandboxId) document.querySelector('.rhema-sandbox-arrows')?.classList.add('visible');
}

function rhemaFilterBooks(query) {
  const q = query.toLowerCase().trim();
  const list = document.getElementById('rhemaBookList');
  if (!list) return;
  list.querySelectorAll('.rhema-book-row').forEach(row => {
    const name = row.querySelector('.rhema-book-name')?.textContent?.toLowerCase() || '';
    row.style.display = (!q || name.includes(q)) ? '' : 'none';
  });
  ['OT', 'NT'].forEach(t => {
    const sep = list.querySelector(`.rhema-testament-sep[data-sep="${t}"]`);
    if (!sep) return;
    const anyVisible = [...list.querySelectorAll(`.rhema-book-row[data-testament="${t}"]`)]
      .some(r => r.style.display !== 'none');
    sep.style.display = anyVisible ? '' : 'none';
  });
}

// Selecting any reference always opens the whole chapter; the verse picker
// then jumps to (and marks) a verse inside it.
function _rhemaOpenSelectedReference() {
  _rhemaFullChapter = true;
  _rhemaSyntaxMode = false;
  _rhemaHighlightStrongs = null;
  _syncRhemaChapterUi();
  closeRhemaPickerSheet();
  syncRhemaPicker();
  renderRhemaVerse();
}

function rhemaSelectBook(code) {
  const fromBook = _rhemaBook;
  _rhemaBook    = code;
  _rhemaChapter = '1';
  _rhemaVerse   = '1';
  _rhemaVerseFocus = false;
  if (isRhemaOTBook(code) && !isRhemaOTBook(fromBook)) _rhemaOTLayer = 'hebrew';
  _rhemaOpenSelectedReference();
}

function rhemaSelectBookChapter(code, ch) {
  const fromBook = _rhemaBook;
  _rhemaBook = code;
  _rhemaChapter = String(ch);
  _rhemaVerse = '1';
  _rhemaVerseFocus = false;
  if (isRhemaOTBook(code) && !isRhemaOTBook(fromBook)) _rhemaOTLayer = 'hebrew';
  _rhemaOpenSelectedReference();
}

function rhemaSelectChap(ch) {
  _rhemaChapter = ch;
  _rhemaVerse   = '1';
  _rhemaVerseFocus = false;
  _rhemaOpenSelectedReference();
}

function rhemaSelectVerse(v) {
  _rhemaVerse = v;
  _rhemaVerseFocus = true;
  _rhemaHighlightStrongs = null;
  closeRhemaPickerSheet();
  syncRhemaPicker();
  renderRhemaVerse();
}

// ── Verse swipe navigation ────────────────────────────────────────────────────

function updateRhemaVerseNav() {
  const nav    = document.getElementById('rhemaVerseNav');
  const ref    = document.getElementById('rhemaVerseRef');
  const arrows = document.querySelector('.rhema-sandbox-arrows');
  if (!nav) return;
  if (_studySandboxId) {
    // In study sandbox: hide the full bar and show floating arrow pair instead
    nav.classList.add('hidden');
    arrows?.classList.add('visible');
  } else {
    nav.classList.remove('hidden');
    arrows?.classList.remove('visible');
    if (ref && _rhemaData()) {
      const bookName = _rhemaBookName(_rhemaBook);
      ref.textContent = _rhemaFullChapter
        ? `${bookName} ${_rhemaChapter}`
        : `${bookName} ${_rhemaChapter}:${_rhemaVerse}`;
    }
  }
}

function initRhemaVerseSwipe() {
  // Only attach to the verse scroll area — not the header, picker, breadcrumb,
  // highlight bar, or word-detail sheet which each have their own scroll behaviour
  const area = document.querySelector('#rhemaModal .rhema-body');
  if (!area || area._hSwipeInit) return;
  area._hSwipeInit = true;
  let sx = 0, sy = 0, _swipeInDiagram = false;
  area.addEventListener('touchstart', e => {
    sx = e.touches[0].clientX;
    sy = e.touches[0].clientY;
    _swipeInDiagram = !!e.target.closest('.rsx-diagram');
  }, { passive: true });
  area.addEventListener('touchend', e => {
    // Disable swipe navigation entirely when the syntax tree is visible
    if (_rhemaSyntaxMode || _swipeInDiagram) return;
    const dx = e.changedTouches[0].clientX - sx;
    const dy = e.changedTouches[0].clientY - sy;
    // Require clearly horizontal swipe (≥45px, more horizontal than vertical)
    if (Math.abs(dx) < 45 || Math.abs(dx) < Math.abs(dy) * 1.5) return;
    if (dx < 0) rhemaNextVerse();
    else rhemaPrevVerse();
  }, { passive: true });
}

function rhemaPrevVerse() {
  if (!_rhemaData()) return;
  const chapters = Object.keys(_rhemaText()[_rhemaBook] || {}).sort((a,b) => +a - +b);
  const chIdx = chapters.indexOf(_rhemaChapter);
  if (_rhemaFullChapter) {
    if (chIdx > 0) {
      _rhemaChapter = chapters[chIdx - 1];
      _rhemaVerse = '1';
      _rhemaVerseFocus = false;
    } else return;
  } else {
    const verses = Object.keys((_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {}).sort((a,b) => +a - +b);
    const idx = verses.indexOf(_rhemaVerse);
    if (idx > 0) {
      _rhemaVerse = verses[idx - 1];
    } else {
      if (chIdx > 0) {
        _rhemaChapter = chapters[chIdx - 1];
        const prevVerses = Object.keys((_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {}).sort((a,b) => +a - +b);
        _rhemaVerse = prevVerses[prevVerses.length - 1];
      } else return;
    }
  }
  syncRhemaPicker();
  renderRhemaVerse();
}

function rhemaNextVerse() {
  if (!_rhemaData()) return;
  const chapters = Object.keys(_rhemaText()[_rhemaBook] || {}).sort((a,b) => +a - +b);
  const chIdx = chapters.indexOf(_rhemaChapter);
  if (_rhemaFullChapter) {
    if (chIdx < chapters.length - 1) {
      _rhemaChapter = chapters[chIdx + 1];
      _rhemaVerse = '1';
      _rhemaVerseFocus = false;
    } else return;
  } else {
    const verses = Object.keys((_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {}).sort((a,b) => +a - +b);
    const idx = verses.indexOf(_rhemaVerse);
    if (idx < verses.length - 1) {
      _rhemaVerse = verses[idx + 1];
    } else {
      if (chIdx < chapters.length - 1) {
        _rhemaChapter = chapters[chIdx + 1];
        _rhemaVerse = '1';
      } else return;
    }
  }
  syncRhemaPicker();
  renderRhemaVerse();
}

// ── Cross-reference jumping ───────────────────────────────────────────────────

function jumpToRhemaVerse(book, chapter, verse, highlightStrongs) {
  const fromBook = _rhemaBook;
  // First jump: also record the origin verse so the trail starts from the beginning
  if (_rhemaTrail.length === 0) {
    _rhemaTrail.push({ book: _rhemaBook, chapter: _rhemaChapter, verse: _rhemaVerse, strongs: null });
  }
  _rhemaTrail.push({ book, chapter: String(chapter), verse: String(verse), strongs: highlightStrongs || null });
  _rhemaTrailPos = _rhemaTrail.length - 1;
  _rhemaBook = book;
  _rhemaChapter = String(chapter);
  _rhemaVerse = String(verse);
  if (isRhemaOTBook(book) && !isRhemaOTBook(fromBook)) _rhemaOTLayer = 'hebrew';
  _rhemaHighlightStrongs = highlightStrongs || null;
  _rhemaVerseFocus = true;
  closeRhemaSheet();
  syncRhemaPicker();
  renderRhemaVerse();
  updateRhemaBreadcrumb();
}

function updateRhemaBreadcrumb() {
  const el = document.getElementById('rhemaBreadcrumb');
  if (!el) return;
  if (_rhemaTrail.length === 0) { el.classList.add('hidden'); return; }
  el.classList.remove('hidden');

  const items = _rhemaTrail.map((h, i) => {
    const abbr = RHEMA_BOOK_ABBR[h.book] || h.book;
    const isActive = i === _rhemaTrailPos;
    const cls = isActive
      ? 'rhema-breadcrumb-current rhema-breadcrumb-active'
      : 'rhema-breadcrumb-item';
    return isActive
      ? `<span class="${cls}">${abbr} ${h.chapter}:${h.verse}</span>`
      : `<span class="${cls}" onclick="rhemaJumpHistory(${i})">${abbr} ${h.chapter}:${h.verse}</span>`;
  });
  if (_rhemaTrailPos === -1) {
    const curAbbr = RHEMA_BOOK_ABBR[_rhemaBook] || _rhemaBook;
    items.push(`<span class="rhema-breadcrumb-current rhema-breadcrumb-active">${curAbbr} ${_rhemaChapter}:${_rhemaVerse}</span>`);
  }

  el.innerHTML =
    `<div class="rhema-breadcrumb-scroll">${items.join('<span class="rhema-breadcrumb-arrow"> › </span>')}</div>` +
    `<button class="rhema-breadcrumb-clear" onclick="rhemaClearHistory()">✕ Clear</button>`;

  // Scroll to show the active/current item
  requestAnimationFrame(() => {
    const scroll = el.querySelector('.rhema-breadcrumb-scroll');
    if (scroll) scroll.scrollLeft = scroll.scrollWidth;
  });
}

function rhemaJumpHistory(idx) {
  const target = _rhemaTrail[idx];
  if (!target) return;
  _rhemaTrailPos = idx;
  _rhemaBook = target.book;
  _rhemaChapter = target.chapter;
  _rhemaVerse = target.verse;
  _rhemaHighlightStrongs = target.strongs || null;
  closeRhemaSheet();
  syncRhemaPicker();
  renderRhemaVerse();
  updateRhemaBreadcrumb();
}

function rhemaClearHistory() {
  _rhemaTrail = [];
  _rhemaTrailPos = -1;
  _rhemaHighlightStrongs = null;
  updateRhemaBreadcrumb();
}

// ── Verse rendering ───────────────────────────────────────────────────────────

function _escapeRhemaAttr(value = '') {
  return String(value).replace(/[&<>"']/g, ch => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[ch]));
}

function _normalizeRhemaSurface(value = '') {
  return String(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[()⸀⸂⸃⸆⸇.,;··]/g, '')
    .replace(/ς/g, 'σ')
    .toLowerCase();
}

function _rhemaVariantMap(words, verse) {
  if (!_rhemaData() || !window.RhemaCriticalNT?.text || !RHEMA_NT_BOOK_ORDER.includes(_rhemaBook)) return {};
  const otherText = _rhemaTextForMode(_rhemaOtherTextMode());
  const otherWords = (otherText[_rhemaBook] || {})[_rhemaChapter]?.[verse || _rhemaVerse] || [];
  if (!otherWords.length) return {};

  const a = words.map(w => _normalizeRhemaSurface(w[0]));
  const b = otherWords.map(w => _normalizeRhemaSurface(w[0]));
  const dp = Array.from({ length: a.length + 1 }, () => Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }

  const variants = {};
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) {
      i++; j++;
      continue;
    }
    const startI = i;
    const startJ = j;
    while (i < a.length || j < b.length) {
      if (i < a.length && j < b.length && a[i] === b[j]) break;
      if (j >= b.length || (i < a.length && dp[i + 1][j] >= dp[i][j + 1])) i++;
      else j++;
    }
    const currentPhrase = words.slice(startI, i).map(w => w[0]).join(' ').trim();
    const otherPhrase = otherWords.slice(startJ, j).map(w => w[0]).join(' ').trim();
    if (!otherPhrase && !currentPhrase) continue;
    const label = _rhemaTextMode === 'critical' ? 'Majority' : 'Critical';
    const text = otherPhrase || `omits ${currentPhrase}`;
    const from = startI < i ? startI : Math.max(0, startI - 1);
    const to = startI < i ? i : Math.min(words.length, from + 1);
    for (let k = from; k < to; k++) variants[k] = { label, text };
  }
  return variants;
}

function showRhemaVariant(label, text) {
  const toast = document.getElementById('rhemaChapterToast');
  if (!toast) return;
  toast.classList.add('hidden');
  toast.style.animation = 'none';
  void toast.offsetWidth;
  toast.style.animation = '';
  toast.textContent = `${label}: ${text}`;
  toast.classList.remove('hidden');
  clearTimeout(showRhemaVariant._timer);
  showRhemaVariant._timer = setTimeout(() => toast.classList.add('hidden'), 2600);
}

function _rhemaLayerBadge(bookCode = _rhemaBook) {
  const layer = getCurrentOriginalLanguageLayer(bookCode);
  if (layer === 'hebrew') return '<div class="rhema-layer-label">Hebrew OT</div>';
  if (layer === 'lxx') return '<div class="rhema-layer-label">LXX · Septuagint Greek</div>';
  return '';
}

const RHEMA_SURFACE_STRONGS_FALLBACKS = {
  συνιστανειν: '4921',
  μωυσεωσ: '3475',
  μωυσησ: '3475',
  καλυμμα: '2571',
  μεταμορφουμεθα: '3339',
  εινεκεν: '1752',
};

const RHEMA_CONTEXTUAL_BRIEFS = {
  '2CO 3': {
    757: 'I begin',
    4921: 'I commend, recommend',
    4956: 'recommendation',
    1992: 'letter',
    4006: 'confidence',
    2316: 'God',
    5547: 'Christ',
    1247: 'I serve, minister',
    4151: 'Spirit',
    2588: 'heart',
    2425: 'sufficient',
    2426: 'sufficiency',
    2427: 'I make sufficient',
    1249: 'servant, minister',
    2537: 'new',
    1242: 'covenant',
    1121: 'letter, written code',
    1248: 'ministry',
    1391: 'glory',
    2571: 'veil',
    2673: 'I make powerless, bring to an end',
    3954: 'boldness, confidence',
    3820: 'old',
    343: 'I unveil',
    2962: 'Lord',
    3475: 'Moses',
    1657: 'freedom',
    2734: 'I behold as in a mirror, reflect',
    3339: 'I transform',
  },
};

function _rhemaResolveWord(word = [], book = _rhemaBook, chapter = _rhemaChapter) {
  if (!Array.isArray(word)) return word;
  if (word[1]) return word;
  const key = _rhemaGreekSurfaceKey(word[0]);
  const fallback = RHEMA_SURFACE_STRONGS_FALLBACKS[key] || window.RhemaCriticalFallbacks?.[key];
  return fallback ? [word[0], fallback, word[2] || '', word[3] || ''] : word;
}

function _rhemaContextualBrief(word = [], book = _rhemaBook, chapter = _rhemaChapter) {
  const strongs = parseInt(word?.[1], 10);
  if (!strongs) return '';
  const morph = String(word?.[2] || '');
  const surfaceKey = _rhemaGreekSurfaceKey(word?.[0] || '');

  // G757 has two legitimate senses. In the middle voice, as in 2 Cor 3:1
  // Ἀρχόμεθα, it is ἄρχομαι: "begin," not "rule/reign."
  if (strongs === 757 && morph.startsWith('V-') && morph[3] === 'M' && surfaceKey.startsWith('αρχ')) {
    return 'I begin';
  }

  return RHEMA_CONTEXTUAL_BRIEFS[`${book} ${chapter}`]?.[strongs] || '';
}

function _rhemaContextualPronounGloss(word = []) {
  const strongs = parseInt(word?.[1], 10);
  const morph = String(word?.[2] || '');
  const cng = morph.split('-')[1] || '';
  if (!strongs || !cng) return '';
  const caseCode = cng[0] === '1' || cng[0] === '2' ? cng[1] : cng[0];
  const numberCode = cng[0] === '1' || cng[0] === '2' ? cng[2] : cng[1];

  if (strongs === 1473) {
    if (numberCode === 'P') return ({ N: 'we', G: 'our', D: 'to/for us', A: 'us' })[caseCode] || '';
    return ({ N: 'I', G: 'my', D: 'to/for me', A: 'me' })[caseCode] || '';
  }
  if (strongs === 4771) {
    if (numberCode === 'P') return ({ N: 'you all', G: 'your', D: 'to/for you', A: 'you' })[caseCode] || '';
    return ({ N: 'you', G: 'your', D: 'to/for you', A: 'you' })[caseCode] || '';
  }
  if (strongs === 1438) {
    if (numberCode === 'P') return ({ G: 'ourselves', D: 'to/for ourselves', A: 'ourselves' })[caseCode] || 'ourselves';
    return ({ G: 'himself', D: 'to/for himself', A: 'himself' })[caseCode] || 'himself';
  }
  if (strongs === 846) {
    if (numberCode === 'P') return ({ N: 'they', G: 'their', D: 'to/for them', A: 'them' })[caseCode] || '';
    return ({ N: 'he/she/it', G: 'his/her/its', D: 'to/for him/her/it', A: 'him/her/it' })[caseCode] || '';
  }
  return '';
}

function _rhemaLexForWord(word = [], layer = getCurrentOriginalLanguageLayer(), book = _rhemaBook, chapter = _rhemaChapter) {
  const resolved = _rhemaResolveWord(word, book, chapter);
  const lex = getCurrentRhemaLexicon(layer)[resolved?.[1]] || {};
  const brief = layer === 'hebrew' ? '' : _rhemaContextualBrief(resolved, book, chapter);
  const pronounGloss = layer === 'hebrew' ? '' : _rhemaContextualPronounGloss(resolved);
  if (!brief && !pronounGloss) return lex;
  const patched = { ...lex };
  if (brief) patched.brief = brief;
  if (pronounGloss) {
    patched._rhemaPronounGloss = pronounGloss;
    if (!brief) patched.brief = pronounGloss;
  }
  if (!patched.extended || patched.extended === lex.brief || /^I reign, rule\.?$/i.test(patched.extended)) {
    const text = brief || pronounGloss;
    patched.extended = text.endsWith('.') ? text : `${text}.`;
  }
  if (parseInt(resolved?.[1], 10) === 757 && brief === 'I begin') {
    patched.lemma = 'ἄρχομαι';
    patched.translit = 'árchomai';
  }
  return patched;
}

function _rhemaDeepEntrySync(strongs) {
  const num = parseInt(strongs, 10);
  if (!num) return null;
  const lo = Math.floor((num - 1) / 100) * 100 + 1;
  return _deepLexiconData.get(lo)?.[num] || null;
}

function _rhemaMeaningDecision(word = [], {
  layer = getCurrentOriginalLanguageLayer(),
  book = _rhemaBook,
  chapter = _rhemaChapter,
  verse = _rhemaVerse,
  entry = null,
} = {}) {
  const resolved = _rhemaResolveWord(word, book, chapter);
  const strongs = resolved?.[1];
  const morph = resolved?.[2] || '';
  const lex = _rhemaLexForWord(resolved, layer, book, chapter);
  if (layer === 'hebrew') {
    const text = getRhemaQuickDefinition(lex);
    return { word: resolved, lex, gloss: text, definition: text, source: 'Hebrew lexicon', confidence: 'Reference', evidence: [] };
  }

  const pos = String(morph || '').split('-')[0];
  const inflectedGloss = _rhemaBaseInterlinearGloss(morph, lex);
  const summary = _rhemaDefinitionSummary(lex);
  const contextual = _rhemaContextualBrief(resolved, book, chapter);
  const loadedEntry = entry || _rhemaDeepEntrySync(strongs);
  const ref = book && chapter && verse && isRhemaNTBook(book) ? `${book} ${chapter}:${verse}` : '';
  let deep = null;
  if (loadedEntry?.senses?.length) {
    const idx = ref && loadedEntry.verseSense && ref in loadedEntry.verseSense
      ? loadedEntry.verseSense[ref]
      : 0;
    const deepSummary = _deepDefinitionSummary(loadedEntry, idx);
    if (deepSummary.text) deep = { ...deepSummary, senseIndex: idx };
  } else if (loadedEntry?.prose?.def) {
    const deepSummary = _deepDefinitionSummary(loadedEntry, null);
    if (deepSummary.text) deep = { ...deepSummary, senseIndex: null };
  }

  const formFirst = pos === 'V' || pos === 'N' || pos === 'P' || pos === 'F' || pos === 'T' ||
    pos === 'A' || pos === 'D' || pos === 'R' || pos === 'I' || pos === 'X';
  const deepSafeForGrid = deep && !_deepLooksLikeAlignmentArtifact(deep.text) &&
    !['V', 'N', 'P', 'F', 'T'].includes(pos);
  const gloss = contextual
    ? (inflectedGloss || contextual)
    : formFirst
      ? (inflectedGloss || summary.text || deep?.text || '')
      : (deepSafeForGrid ? deep.text : (inflectedGloss || summary.text || deep?.text || ''));
  const definition = contextual
    ? (summary.text || contextual || gloss || '')
    : (deep?.text || summary.text || gloss || '');
  const confidence = contextual
    ? 'Context checked'
    : deep?.source
      ? (loadedEntry?.confidence ? (_DEEP_CONFIDENCE_LABELS[loadedEntry.confidence] || loadedEntry.confidence) : deep.source)
      : (summary.confidence || 'Reference');
  const source = contextual
    ? 'Greek form + chapter context'
    : deep?.source || summary.source || 'Loaded lexicon';
  const evidence = [];
  if (inflectedGloss) evidence.push(`Form gloss: ${inflectedGloss}.`);
  if (contextual) evidence.push(`Context note: ${_rhemaBookName(book)} ${chapter} favors "${contextual}".`);
  if (deep?.text) {
    evidence.push(`Rhema Lexicon: ${deep.text}${deep.source ? ` (${deep.source})` : ''}.`);
    if (deep.raw && deep.raw !== deep.text) {
      evidence.push(_deepLooksLikeAlignmentArtifact(deep.raw)
        ? `Measured English phrase includes "${deep.raw}", but that looks like surrounding wording.`
        : `Measured rendering evidence includes "${deep.raw}".`);
    }
  }
  if (summary.text && summary.text !== definition) evidence.push(`Reference gloss: ${summary.text}.`);

  return { word: resolved, lex, gloss, definition, source, confidence, evidence, inflectedGloss, summary, deep, entry: loadedEntry };
}

function _renderVerseWords(words, verse) {
  const vArg = verse ? `, '${verse}'` : '';
  const variantMap = _rhemaVariantMap(words, verse);
  const layer = getCurrentOriginalLanguageLayer();
  const isHebrew = layer === 'hebrew';
  if (_rhemaGreekOnly) {
    return words.map((w, i) => {
      const isXref = _rhemaHighlightStrongs !== null && w[1] === _rhemaHighlightStrongs;
      const posKey = _rhemaOriginalHighlightKey(w);
      const hlColor = _rhemaPosHighlights.has(posKey) ? HIGHLIGHT_CATS[posKey]?.color : null;
      const style = hlColor ? ` style="background:${hlColor};border-radius:4px"` : '';
      const variant = variantMap[i];
      const cls = `${isXref ? 'rhema-word xref' : 'rhema-word'}${variant ? ' has-variant' : ''}`;
      const variantTag = variant
        ? `<button class="rhema-variant-tag" onclick="event.stopPropagation();showRhemaVariant('${variant.label}', '${_escapeRhemaAttr(variant.text)}')" title="Text variant">var</button>`
        : '';
      return `<span class="${cls}"${style} data-idx="${i}" onclick="openRhemaSheet(${i}${vArg})"><span class="rhema-greek-text rhema-original-text${isHebrew ? ' rhema-hebrew-text' : ''}">${w[0]}</span>${variantTag}</span>` +
             (i < words.length - 1 ? '<span class="rhema-word-space"> </span>' : '');
    }).join('');
  } else {
    return words.map((w, i) => {
      const word = _rhemaResolveWord(w, _rhemaBook, _rhemaChapter);
      const isXref = _rhemaHighlightStrongs !== null && String(word[1]) === String(_rhemaHighlightStrongs);
      const posKey = _rhemaOriginalHighlightKey(word);
      const hlColor = _rhemaPosHighlights.has(posKey) ? HIGHLIGHT_CATS[posKey]?.color : null;
      const style = hlColor ? ` style="background:${hlColor};border-radius:4px"` : '';
      const variant = variantMap[i];
      const cls = `${isXref ? 'rhema-word xref' : 'rhema-word'}${variant ? ' has-variant' : ''}`;
      const decision = _rhemaMeaningDecision(word, { layer, book: _rhemaBook, chapter: _rhemaChapter, verse: verse || _rhemaVerse });
      const gloss = decision.gloss;
      const glossHtml = gloss ? `<span class="rhema-gloss">${gloss}</span>` : '';
      const variantTag = variant
        ? `<button class="rhema-variant-tag" onclick="event.stopPropagation();showRhemaVariant('${variant.label}', '${_escapeRhemaAttr(variant.text)}')" title="Text variant">var</button>`
        : '';
      return `<span class="${cls}"${style} data-idx="${i}" onclick="openRhemaSheet(${i}${vArg})"><span class="rhema-greek-text rhema-original-text${isHebrew ? ' rhema-hebrew-text' : ''}">${w[0]}</span>${variantTag}${glossHtml}</span>`;
    }).join('');
  }
}

// Scroll position of a chapter block measured against the scroll container
// itself — block.offsetTop is relative to the modal, which includes the
// header/picker height and lands the verse hidden behind the top bar.
function _rhemaBlockScrollTop(body, block) {
  return block.getBoundingClientRect().top - body.getBoundingClientRect().top + body.scrollTop;
}

function renderRhemaVerse() {
  if (!_rhemaData()) return;
  closeRhemaSheet();
  closeRhemaSyntaxSheet();

  const display = document.getElementById('rhemaVerseDisplay');
  const EnglishDiv  = document.getElementById('rhemaEnglishDisplay');
  if (!display) return;
  const layer = getCurrentOriginalLanguageLayer();
  const isHebrew = layer === 'hebrew';
  if (isHebrew && _rhemaSyntaxMode) _rhemaSyntaxMode = false;
  display.classList.toggle('rhema-hebrew-layer', isHebrew);
  display.classList.toggle('rhema-lxx-layer', layer === 'lxx');

  if (_rhemaFullChapter) {
    const chapterData = (_rhemaText()[_rhemaBook] || {})[_rhemaChapter] || {};
    const verseNums = Object.keys(chapterData).map(Number).sort((a, b) => a - b);
    const focusVerse = (_rhemaHighlightStrongs !== null || _rhemaVerseFocus) ? _rhemaVerse : null;

    display.classList.remove('greek-only');
    display.classList.toggle('chapter-mode', !_rhemaSyntaxMode);
    display.classList.toggle('rsx-chapter-mode', _rhemaSyntaxMode);
    display.innerHTML = _rhemaLayerBadge() + verseNums.map(vn => {
      const v = String(vn);
      const words = chapterData[v] || [];
      const isTarget = v === focusVerse;
      const inner = _rhemaSyntaxMode
        ? _renderSyntaxView(words, v)
        : `<div class="rhema-chapter-word-grid${_rhemaGreekOnly ? ' greek-only' : ''}${isHebrew ? ' rhema-hebrew-layer' : ''}">${_renderVerseWords(words, v)}</div>`;
      return `<div class="rhema-chapter-block${isTarget ? ' rhema-chapter-block-target' : ''}" data-verse="${v}">` +
             `<div class="rhema-chapter-verse-label">${vn}</div>` + inner + `</div>`;
    }).join('');

    if (EnglishDiv) {
      EnglishDiv.classList.toggle('rhema-english-reading', !_rhemaSyntaxMode);
      EnglishDiv.innerHTML = _rhemaSyntaxMode ? '' :
        `<div class="rhema-english-chapter-title">${_escapeRhemaAttr(_rhemaBookName(_rhemaBook))} ${_escapeRhemaAttr(_rhemaChapter)}</div>` +
        verseNums.map(vn => {
          const v = String(vn);
          const engText = _rhemaEnglishText(_rhemaBook, _rhemaChapter, v);
          const engContent = engText
            ? _renderRhemaEnglishText(engText, _rhemaBook, _rhemaChapter, v)
            : `<em class="rhema-no-english">This verse is not included in the ${_rhemaEnglishLabel()} translation.</em>`;
          return `<div class="rhema-chapter-block rhema-english-verse${v === focusVerse ? ' rhema-chapter-block-target' : ''}" data-verse="${v}" onclick="rhemaFocusEnglishVerse('${v}')">` +
                 `<sup class="rhema-english-vnum">${vn}</sup>${engContent}${_rhemaInlineNoteHtml(_rhemaBook, _rhemaChapter, v)}</div>`;
        }).join('');
    }

    requestAnimationFrame(() => {
      const body = document.querySelector('#rhemaModal .rhema-body');
      if (!body) return;
      // A fresh chapter open starts at the top; only scroll when jumping to a
      // focused verse or resuming somewhere mid-chapter.
      if (!focusVerse && _rhemaVerse === String(verseNums[0])) { body.scrollTop = 0; return; }
      const visibleDisplay = _rhemaShowEnglish && !_rhemaSyntaxMode && EnglishDiv ? EnglishDiv : display;
      const target = visibleDisplay.querySelector(`.rhema-chapter-block[data-verse="${_rhemaVerse}"]`);
      if (target) body.scrollTop = Math.max(0, _rhemaBlockScrollTop(body, target) - 12);
    });
  } else {
    const words = (_rhemaText()[_rhemaBook] || {})[_rhemaChapter]?.[_rhemaVerse] || [];
    display.classList.remove('chapter-mode', 'rsx-chapter-mode');
    EnglishDiv?.classList.remove('rhema-english-reading');
    if (_rhemaSyntaxMode) {
      display.classList.remove('greek-only');
      if (_rhemaShowEnglish) {
        const engText = _rhemaEnglishText(_rhemaBook, _rhemaChapter, _rhemaVerse);
        display.innerHTML = _renderEnglishSyntaxView(engText);
        _requestRhemaEnglishSyntaxRender();
      } else {
        display.innerHTML = _rhemaLayerBadge() + _renderSyntaxView(words, null);
      }
      if (EnglishDiv) EnglishDiv.innerHTML = '';
      requestAnimationFrame(() => _initDiagramScroll(display.querySelector('.rsx-diagram')));
    } else {
      display.classList.toggle('greek-only', _rhemaGreekOnly);
      display.innerHTML = _rhemaLayerBadge() + _renderVerseWords(words, null);
      if (EnglishDiv) {
        const engText = _rhemaEnglishText(_rhemaBook, _rhemaChapter, _rhemaVerse);
        EnglishDiv.innerHTML = engText
          ? _renderRhemaEnglishText(engText, _rhemaBook, _rhemaChapter, _rhemaVerse) + _rhemaInlineNoteHtml(_rhemaBook, _rhemaChapter, _rhemaVerse)
          : `<em class="rhema-no-english">This verse is not included in the ${_rhemaEnglishLabel()} translation.</em>`;
      }
    }
  }

  _syncRhemaChapterUi();
  updateRhemaSwapVisibility();
  updateRhemaVerseNav();
  initRhemaVerseSwipe();
  updateHighlightToolbar();
  _syncToolWandIndicator();
  _saveRhemaPosition();
  if (_studySandboxId) _initStudyLongPress();
}

// Top-most verse currently scrolled into view in a chapter display, so mode
// swaps can keep the reader's place instead of snapping back to verse 1.
function _rhemaChapterScrollVerse(displayEl) {
  const body = document.querySelector('#rhemaModal .rhema-body');
  if (!body || !displayEl) return null;
  const bodyTop = body.getBoundingClientRect().top;
  let current = null;
  for (const block of displayEl.querySelectorAll('.rhema-chapter-block')) {
    if (block.getBoundingClientRect().top - bodyTop <= 40) current = block;
    else break;
  }
  return current?.dataset?.verse || null;
}

function toggleRhemaEnglish() {
  _rhemaShowEnglish = !_rhemaShowEnglish;
  if (_rhemaFullChapter && !_rhemaSyntaxMode && !_rhemaVerseFocus) {
    // The display being swapped away from is the opposite of the new state
    const prev = document.getElementById(_rhemaShowEnglish ? 'rhemaVerseDisplay' : 'rhemaEnglishDisplay');
    const verse = _rhemaChapterScrollVerse(prev);
    if (verse) { _rhemaVerse = verse; syncRhemaPicker(); }
  }
  renderRhemaVerse();
  _requestRhemaEnglishHighlightRender();
  closeRhemaSheet();
}

function toggleRhemaEnglishVersion() {
  _rhemaEnglishMode = _rhemaEnglishVersion() === 'BSB' ? 'MSB' : 'BSB';
  localStorage.setItem('rhemaEnglishVersion', _rhemaEnglishMode);
  _syncRhemaEnglishAlias();
  _syncRhemaChapterUi();
  closeRhemaSheet();
  renderRhemaVerse();
  updateRhemaSwapVisibility();
  _requestRhemaEnglishHighlightRender();
}

function toggleRhemaMode() {
  _rhemaGreekOnly = !_rhemaGreekOnly;
  _syncWheelBtn('greek-only', _rhemaGreekOnly);
  _syncToolWandIndicator();
  renderRhemaVerse();
}

function toggleRhemaTextMode() {
  if (!isRhemaNTBook(_rhemaBook)) {
    showRhemaVariant('Text Mode', 'Critical/Majority applies to New Testament Greek. Old Testament uses Hebrew, with LXX available as its own toolbar layer.');
    closeRhemaWheel();
    return;
  }
  if (!window.RhemaCriticalNT?.text || !RHEMA_NT_BOOK_ORDER.includes(_rhemaBook)) {
    showRhemaVariant('Text Mode', 'Critical/Majority applies to New Testament Greek. Old Testament uses Hebrew, with LXX available as its own toolbar layer.');
    closeRhemaWheel();
    return;
  }
  _rhemaTextMode = _rhemaTextMode === 'critical' ? 'majority' : 'critical';
  localStorage.setItem('rhemaTextMode', _rhemaTextMode);
  _syncRhemaEnglishAlias();
  _syncRhemaTextModeBtn();
  _syncToolWandIndicator();
  renderRhemaVerse();
  closeRhemaWheel();
}

// ── Tool Wheel ────────────────────────────────────────────────────────────────

function openRhemaWheel() {
  const overlay = document.getElementById('rhemaWheelOverlay');
  if (!overlay) return;
  document.querySelector('.rhema-sandbox-arrows')?.classList.remove('visible');
  _syncWheelState();
  _updateCopyVerseLabel();
  overlay.style.display = 'flex';
  requestAnimationFrame(() => overlay.classList.add('open'));
}

function closeRhemaWheel() {
  const overlay = document.getElementById('rhemaWheelOverlay');
  if (!overlay) return;
  overlay.classList.remove('open');
  setTimeout(() => { if (!overlay.classList.contains('open')) overlay.style.display = 'none'; }, 300);
  if (_studySandboxId) document.querySelector('.rhema-sandbox-arrows')?.classList.add('visible');
}

function toggleRhemaWheel() {
  const overlay = document.getElementById('rhemaWheelOverlay');
  if (!overlay) return;
  overlay.classList.contains('open') ? closeRhemaWheel() : openRhemaWheel();
}

function toggleWheelTool(tool) {
  if (tool === 'syntax') {
    if (_rhemaFullChapter) {
      const btn = document.getElementById('wheelItemSyntax');
      if (btn) { btn.classList.add('shake'); setTimeout(() => btn.classList.remove('shake'), 500); }
      showRhemaVariant('Syntax', 'Switch to verse-only mode before opening a syntax tree.');
      return;
    }
    if (isRhemaOTBook(_rhemaBook) && getCurrentOriginalLanguageLayer() === 'hebrew') {
      const btn = document.getElementById('wheelItemSyntax');
      if (btn) { btn.classList.add('shake'); setTimeout(() => btn.classList.remove('shake'), 500); }
      showRhemaVariant('Syntax', 'Syntax view is not available for Hebrew.');
      closeRhemaWheel();
      return;
    }
    _rhemaSyntaxMode = !_rhemaSyntaxMode;
    _syncWheelBtn('syntax', _rhemaSyntaxMode);
    _syncToolWandIndicator();
    renderRhemaVerse();
    if (_rhemaSyntaxMode) {
      closeRhemaWheel();
      setTimeout(() => startRhemaSyntaxCoach(), 360); // wait for wheel close animation
    }
  } else if (tool === 'highlight') {
    toggleRhemaHighlightBar();
    _syncToolWandIndicator();
  } else if (tool === 'greek-only') {
    toggleRhemaMode();
  } else if (tool === 'wordlibrary') {
    closeRhemaWheel();
    setTimeout(() => openWordLibrary(), 200);
  } else if (tool === 'critical') {
    toggleRhemaTextMode();
  } else if (tool === 'lxx') {
    if (!isRhemaOTBook(_rhemaBook)) {
      toggleRhemaChapterMode();
      closeRhemaWheel();
      return;
    }
    setRhemaOTLayer(_rhemaOTLayer === 'lxx' ? 'hebrew' : 'lxx');
    closeRhemaWheel();
  }
}

function _syncWheelBtn(tool, active) {
  const ids = { syntax: 'wheelItemSyntax', 'greek-only': 'wheelItemGreek', highlight: 'wheelItemHighlight', critical: 'wheelItemCritical', lxx: 'wheelItemLxx' };
  document.getElementById(ids[tool])?.classList.toggle('active', active);
}

function _syncRhemaTextModeBtn() {
  const btn = document.getElementById('wheelItemCritical');
  if (!btn) return;
  const label = btn.querySelector('.rwi-label');
  if (label) label.textContent = _rhemaTextMode === 'critical' ? 'Majority Text' : 'Critical Text';
  btn.classList.toggle('active', _rhemaTextMode === 'critical');
  btn.classList.toggle('disabled', !isRhemaNTBook(_rhemaBook));
}

function _syncRhemaLxxBtn() {
  const btn = document.getElementById('wheelItemLxx');
  if (!btn) return;
  const isOT = isRhemaOTBook(_rhemaBook);
  const icon = btn.querySelector('.material-symbols-outlined');
  const label = btn.querySelector('.rwi-label');
  if (icon) icon.textContent = isOT ? 'language' : (_rhemaFullChapter ? 'article' : 'short_text');
  if (label) label.textContent = isOT ? 'LXX' : (_rhemaFullChapter ? 'Chapter' : 'Verse');
  btn.classList.remove('hidden');
  btn.classList.remove('disabled');
  btn.classList.toggle('active', isOT ? _rhemaOTLayer === 'lxx' : _rhemaFullChapter);
  btn.title = isOT
    ? 'Swap Old Testament original-language layer between Hebrew and Septuagint Greek'
    : (_rhemaFullChapter ? 'Full chapter is on. Tap for verse-only mode.' : 'Verse-only mode is on. Tap for full chapter.');
}

function _syncRhemaGreekOnlyBtn() {
  const btn = document.getElementById('wheelItemGreek');
  if (!btn) return;
  const isHebrew = isRhemaOTBook(_rhemaBook) && getCurrentOriginalLanguageLayer() === 'hebrew';
  const label = btn.querySelector('.rwi-label');
  if (label) label.textContent = isHebrew ? 'Hebrew Only' : 'Greek Only';
  btn.classList.toggle('active', _rhemaGreekOnly);
}

function _syncRhemaSyntaxBtn() {
  const btn = document.getElementById('wheelItemSyntax');
  if (!btn) return;
  const isHebrew = isRhemaOTBook(_rhemaBook) && getCurrentOriginalLanguageLayer() === 'hebrew';
  const disabled = isHebrew || _rhemaFullChapter;
  btn.classList.toggle('disabled', disabled);
  btn.title = isHebrew
    ? 'Syntax view is not available for Hebrew'
    : _rhemaFullChapter
      ? 'Switch to verse-only mode before opening syntax'
      : '';
}

function _syncWheelState() {
  _syncWheelBtn('syntax', _rhemaSyntaxMode);
  _syncWheelBtn('greek-only', _rhemaGreekOnly);
  _syncWheelBtn('highlight', _rhemaHighlightBarOn);
  _syncWheelBtn('critical', _rhemaTextMode === 'critical');
  _syncWheelBtn('lxx', isRhemaOTBook(_rhemaBook) && _rhemaOTLayer === 'lxx');
  _syncRhemaTextModeBtn();
  _syncRhemaLxxBtn();
  _syncRhemaGreekOnlyBtn();
  _syncRhemaSyntaxBtn();
  document.getElementById('wheelItemXref')?.classList.toggle('active', _rhemaCrossRefMode);
}

function _syncToolWandIndicator() {
  const hasActive = _rhemaSyntaxMode || _rhemaGreekOnly || _rhemaHighlightBarOn || _rhemaTextMode === 'critical' || (isRhemaOTBook(_rhemaBook) && _rhemaOTLayer === 'lxx');
  document.getElementById('rhemaToolBtn')?.classList.toggle('has-active', hasActive);
}

